-- ===========================================================
-- 0006_inventory.sql
-- ===========================================================
-- 0006 Suppliers, item catalogue, stock locations and movements
--
-- Stock level is derived from movements and never written directly. A level
-- that can be edited is a level nobody trusts by month three.

create table suppliers (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  name text not null,
  contact_name text,
  phone text,
  email text,
  account_no text,
  -- Rental vendors are suppliers too; equipment_rentals points here.
  is_rental_vendor boolean not null default false,
  notes text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table inventory_items (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  sku text not null,
  name text not null,
  category text,
  unit_of_measure text not null default 'each',
  barcode text,
  -- Weighted average, recalculated on receipt. Used for the materials line
  -- of job costing.
  average_cost numeric(12,4) not null default 0,
  preferred_supplier_id uuid references suppliers(id),
  min_level numeric(12,3) not null default 0,
  reorder_quantity numeric(12,3) not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, sku)
);

create index on inventory_items (org_id) where is_active;
create unique index inventory_items_barcode on inventory_items (org_id, barcode)
  where barcode is not null;

create type stock_location_kind as enum ('warehouse', 'van', 'site', 'supplier');

-- Van stock is the reason locations exist. "How much Concrobium is in Van 2"
-- is the question actually asked.
create table stock_locations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  name text not null,
  kind stock_location_kind not null default 'warehouse',
  vehicle_id uuid,           -- FK added in 0008, once vehicles exists
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create type stock_movement_kind as enum (
  'receipt', 'usage', 'transfer', 'adjustment', 'count', 'return'
);

-- Append-only ledger. Every change to stock lands here and nowhere else.
create table stock_movements (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  item_id uuid not null references inventory_items(id),
  kind stock_movement_kind not null,
  from_location_id uuid references stock_locations(id),
  to_location_id uuid references stock_locations(id),
  quantity numeric(12,3) not null,
  unit_cost numeric(12,4),
  job_id uuid references jobs(id) on delete set null,
  reference_table text,
  reference_id uuid,
  reason text,
  created_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  constraint stock_movements_quantity_positive check (quantity > 0),
  constraint stock_movements_has_endpoint check (
    from_location_id is not null or to_location_id is not null
  ),
  -- An adjustment with no reason is how stock records become fiction.
  constraint stock_movements_adjustment_reason check (
    kind <> 'adjustment' or (reason is not null and length(trim(reason)) > 0)
  )
);

create index on stock_movements (item_id, created_at desc);
create index on stock_movements (job_id) where job_id is not null;

-- Derived stock on hand. A plain view keeps it always-correct; if read
-- volume ever justifies it this becomes a materialised view refreshed on
-- movement insert.
create view stock_levels
with (security_invoker = true)
as
select
  m.org_id,
  m.item_id,
  loc.id as location_id,
  sum(
    case
      when m.to_location_id = loc.id then m.quantity
      when m.from_location_id = loc.id then -m.quantity
      else 0
    end
  ) as quantity
from stock_movements m
join stock_locations loc
  on loc.id in (m.from_location_id, m.to_location_id)
group by m.org_id, m.item_id, loc.id;

-- Materials consumed on a job. Writes a matching 'usage' movement via
-- trigger in 0012, so the ledger stays the single source of truth.
create table material_usage (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  job_id uuid not null references jobs(id) on delete cascade,
  visit_id uuid references job_visits(id) on delete set null,
  item_id uuid not null references inventory_items(id),
  location_id uuid not null references stock_locations(id),
  quantity numeric(12,3) not null,
  logged_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint material_usage_quantity_positive check (quantity > 0)
);

create index on material_usage (job_id);

select attach_updated_at('suppliers');
select attach_updated_at('inventory_items');
select attach_updated_at('stock_locations');
select attach_updated_at('material_usage');

-- ===========================================================
-- 0007_purchasing.sql
-- ===========================================================
-- 0007 Material purchase requests
--
-- Editing is locked on submit rather than on approval, with a recall action
-- for the requester. Every change from submit onward is captured by an
-- append-only audit trigger (0012) that no role may update or delete.

create type purchase_status as enum (
  'draft', 'submitted', 'under_review', 'approved', 'rejected',
  'ordered', 'partially_received', 'received', 'closed', 'cancelled'
);

create type purchase_line_status as enum ('pending', 'approved', 'rejected');

create sequence purchase_request_number_seq;

create table purchase_requests (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  request_number text not null
    default 'PR' || lpad(nextval('purchase_request_number_seq')::text, 5, '0'),
  requested_by uuid not null references profiles(id),
  -- The manager or owner tagged to action it.
  assigned_to uuid references profiles(id),
  job_id uuid references jobs(id) on delete set null,
  status purchase_status not null default 'draft',
  needed_by date,
  notes text,
  supplier_id uuid references suppliers(id),
  po_number text,
  expected_delivery date,
  receipt_storage_path text,
  decided_by uuid references profiles(id),
  decided_at timestamptz,
  decision_reason text,
  submitted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, request_number)
);

create index on purchase_requests (org_id, status);
create index on purchase_requests (requested_by);
create index on purchase_requests (assigned_to) where status in ('submitted', 'under_review');

create table purchase_request_lines (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  request_id uuid not null references purchase_requests(id) on delete cascade,
  -- Nullable: the field often asks for something not yet in the catalogue.
  item_id uuid references inventory_items(id),
  description text not null,
  quantity numeric(12,3) not null,
  unit text not null default 'each',
  estimated_unit_cost numeric(12,4),
  -- Per-line status is what makes partial approval possible: approve six of
  -- eight lines instead of rejecting the lot and making someone retype it.
  line_status purchase_line_status not null default 'pending',
  rejection_reason text,
  received_quantity numeric(12,3) not null default 0,
  receive_location_id uuid references stock_locations(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint purchase_line_quantity_positive check (quantity > 0),
  constraint purchase_line_received_valid check (received_quantity >= 0)
);

create index on purchase_request_lines (request_id);

create or replace function purchase_request_total(p_request_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(quantity * coalesce(estimated_unit_cost, 0)), 0)
  from purchase_request_lines
  where request_id = p_request_id;
$$;

create or replace function purchase_request_approved_total(p_request_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(quantity * coalesce(estimated_unit_cost, 0)), 0)
  from purchase_request_lines
  where request_id = p_request_id and line_status = 'approved';
$$;

-- Append-only. Written by trigger only (0012); RLS in 0013 grants insert and
-- select but no update or delete, to any role including the owner.
create table purchase_request_audit (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  request_id uuid not null references purchase_requests(id) on delete cascade,
  line_id uuid,
  actor_id uuid references profiles(id),
  at timestamptz not null default now(),
  action text not null,
  field text,
  old_value text,
  new_value text
);

create index on purchase_request_audit (request_id, at desc);

select attach_updated_at('purchase_requests');
select attach_updated_at('purchase_request_lines');

-- ===========================================================
-- 0008_vehicles.sql
-- ===========================================================
-- 0008 Vehicles, mileage, fuel and maintenance
--
-- Mileage is captured as odometer start/end rather than typed distance. It is
-- harder to fudge and it keeps the vehicle's odometer current for service
-- intervals at no extra cost to the person logging it.

create table vehicles (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  name text not null,
  plate text,
  make_model text,
  year int,
  current_odometer numeric(10,1) not null default 0,
  assigned_user_id uuid references profiles(id),
  insurance_expiry date,
  registration_expiry date,
  next_service_odometer numeric(10,1),
  next_service_date date,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on vehicles (org_id) where is_active;

-- A van is both a vehicle and a stock location; this is the link.
alter table stock_locations
  add constraint stock_locations_vehicle_fk
  foreign key (vehicle_id) references vehicles(id) on delete set null;

create table mileage_logs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  vehicle_id uuid not null references vehicles(id),
  user_id uuid not null references profiles(id),
  job_id uuid references jobs(id) on delete set null,
  trip_date date not null default current_date,
  odometer_start numeric(10,1) not null,
  odometer_end numeric(10,1) not null,
  distance numeric(10,1) generated always as (odometer_end - odometer_start) stored,
  purpose text,
  is_business boolean not null default true,
  -- Set when the opening reading does not match the vehicle's last closing
  -- reading. A warning, not a rejection: vehicles get moved without a log,
  -- and a hard block would simply stop people logging at all.
  continuity_gap numeric(10,1),
  notes text,
  edited_by uuid references profiles(id),
  edited_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint mileage_odometer_valid check (odometer_end >= odometer_start)
);

create index on mileage_logs (vehicle_id, trip_date desc);
create index on mileage_logs (user_id, trip_date desc);
create index on mileage_logs (job_id) where job_id is not null;

create table fuel_logs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  vehicle_id uuid not null references vehicles(id),
  user_id uuid references profiles(id),
  filled_on date not null default current_date,
  volume numeric(10,3),
  volume_unit text not null default 'gal',
  cost numeric(10,2),
  odometer numeric(10,1),
  receipt_storage_path text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on fuel_logs (vehicle_id, filled_on desc);

create table vehicle_maintenance (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  vehicle_id uuid not null references vehicles(id),
  performed_on date not null default current_date,
  odometer numeric(10,1),
  kind text not null,
  description text,
  cost numeric(10,2),
  next_due_date date,
  next_due_odometer numeric(10,1),
  created_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on vehicle_maintenance (vehicle_id, performed_on desc);

select attach_updated_at('vehicles');
select attach_updated_at('mileage_logs');
select attach_updated_at('fuel_logs');
select attach_updated_at('vehicle_maintenance');

-- ===========================================================
-- 0009_equipment.sql
-- ===========================================================
-- 0009 Equipment: owned register, placements, rentals
--
-- Three distinct flows, per docs/06-equipment.md:
--   checkout      - goes out with a crew and comes back
--   site_staging  - left running at an address for days
--   rental        - rented in from a vendor for a job
--
-- Billing is flat per job, so equipment days add no revenue. Tracking exists
-- to know where a unit physically is, and to load real cost onto the job.

create type equipment_category as enum (
  'air_scrubber', 'dehumidifier', 'air_mover', 'meter', 'hepa_vacuum',
  'negative_air', 'generator', 'tool', 'other'
);

create type equipment_lifecycle as enum ('active', 'in_maintenance', 'retired', 'lost');

create type equipment_condition as enum ('ok', 'damaged', 'needs_service');

create table equipment (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  -- Printed QR/barcode on the unit. This is what the field scans.
  asset_tag text not null,
  name text not null,
  category equipment_category not null default 'other',
  make text,
  model text,
  serial_no text,
  purchase_date date,
  purchase_cost numeric(12,2),
  -- Internal cost loaded onto a job per day deployed. Set by the owner to
  -- recover purchase cost over the unit's expected life. Never shown to a
  -- customer.
  internal_day_rate numeric(10,2) not null default 0,
  has_hour_meter boolean not null default false,
  filter_interval_hours numeric(10,1),
  home_location_id uuid references stock_locations(id),
  lifecycle_status equipment_lifecycle not null default 'active',
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, asset_tag)
);

create index on equipment (org_id, category) where lifecycle_status = 'active';

create type equipment_placement_kind as enum ('checkout', 'site_staging');

-- One row per continuous placement of one unit.
create table equipment_assignments (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  equipment_id uuid not null references equipment(id) on delete cascade,
  kind equipment_placement_kind not null,
  job_id uuid references jobs(id) on delete set null,
  site_id uuid references sites(id) on delete set null,
  assigned_to_user_id uuid references profiles(id),
  started_at timestamptz not null default now(),
  -- Planned collection. Drives the pickup-due alert.
  expected_end_at timestamptz,
  ended_at timestamptz,
  placed_by uuid references profiles(id),
  collected_by uuid references profiles(id),
  condition_out equipment_condition not null default 'ok',
  condition_in equipment_condition,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint equipment_placement_range_valid check (ended_at is null or ended_at > started_at),
  -- Staging is to a site; checkout is to a person. Enforcing this stops the
  -- two flows quietly collapsing into one ambiguous record.
  constraint equipment_placement_target check (
    (kind = 'site_staging' and site_id is not null)
    or (kind = 'checkout' and assigned_to_user_id is not null)
  )
);

-- THE constraint of this model: one unit can never be in two places at once.
-- Enforced in the database so the scheduler, the mobile scan screen and any
-- future import all inherit it.
alter table equipment_assignments
  add constraint equipment_no_overlap
  exclude using gist (
    equipment_id with =,
    tstzrange(started_at, coalesce(ended_at, 'infinity'::timestamptz)) with &&
  );

create index on equipment_assignments (job_id);
create index on equipment_assignments (site_id) where ended_at is null;
create index equipment_assignments_open on equipment_assignments (equipment_id)
  where ended_at is null;

-- Current whereabouts are derived, never stored. A stored location column
-- drifts within weeks; a view cannot.
create view equipment_current
with (security_invoker = true)
as
select
  e.id            as equipment_id,
  e.org_id,
  e.asset_tag,
  e.name,
  e.category,
  e.lifecycle_status,
  a.id            as assignment_id,
  a.kind,
  a.job_id,
  a.site_id,
  a.assigned_to_user_id,
  a.started_at,
  a.expected_end_at,
  case
    when e.lifecycle_status <> 'active' then e.lifecycle_status::text
    when a.id is null then 'available'
    when a.kind = 'checkout' then 'in_use'
    else 'staged_at_site'
  end as location_status,
  case
    when a.id is null then null
    else greatest(0, extract(epoch from (now() - a.started_at)) / 86400.0)
  end as days_deployed,
  (a.expected_end_at is not null and a.ended_at is null and a.expected_end_at < now())
    as pickup_overdue
from equipment e
left join equipment_assignments a
  on a.equipment_id = e.id and a.ended_at is null;

create type rental_status as enum ('reserved', 'on_hire', 'overdue', 'returned', 'closed', 'cancelled');

-- Rented in from a vendor. Tracked apart from owned equipment because the
-- risk is different: an owned scrubber left behind is an inconvenience, a
-- rental left out is an invoice that grows daily.
create table equipment_rentals (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  supplier_id uuid not null references suppliers(id),
  job_id uuid references jobs(id) on delete set null,
  site_id uuid references sites(id) on delete set null,
  description text not null,
  category equipment_category not null default 'other',
  quantity int not null default 1,
  rate numeric(10,2),
  rate_unit text not null default 'day',
  picked_up_at timestamptz,
  return_due_at timestamptz,
  returned_at timestamptz,
  estimated_cost numeric(12,2),
  -- From the vendor invoice. Falls back to estimated_cost in job costing
  -- while the invoice is outstanding.
  actual_cost numeric(12,2),
  agreement_no text,
  document_path text,
  status rental_status not null default 'reserved',
  created_by uuid references profiles(id),
  returned_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint rental_quantity_positive check (quantity > 0),
  constraint rental_return_valid check (returned_at is null or picked_up_at is null or returned_at >= picked_up_at)
);

create index on equipment_rentals (job_id);
create index on equipment_rentals (status) where status in ('on_hire', 'overdue');

-- Hour-meter readings on scrubbers and dehumidifiers. Drives filter and
-- service intervals, and gives a defensible record of how long containment
-- actually ran.
create table equipment_runtime_logs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  equipment_id uuid not null references equipment(id) on delete cascade,
  job_id uuid references jobs(id) on delete set null,
  reading_hours numeric(10,1) not null,
  read_at timestamptz not null default now(),
  read_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  constraint runtime_reading_positive check (reading_hours >= 0)
);

create index on equipment_runtime_logs (equipment_id, read_at desc);

create table equipment_maintenance (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  equipment_id uuid not null references equipment(id) on delete cascade,
  performed_on date not null default current_date,
  kind text not null,
  description text,
  cost numeric(10,2),
  hours_at_service numeric(10,1),
  next_due_hours numeric(10,1),
  next_due_date date,
  created_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on equipment_maintenance (equipment_id, performed_on desc);

select attach_updated_at('equipment');
select attach_updated_at('equipment_assignments');
select attach_updated_at('equipment_rentals');
select attach_updated_at('equipment_maintenance');

-- ===========================================================
-- 0010_compliance_audit_notifications.sql
-- ===========================================================
-- 0010 Certifications, notifications, global audit log

create table certification_types (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  name text not null,
  issuing_body text,
  validity_months int,
  is_required boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, name)
);

create table user_certifications (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  type_id uuid not null references certification_types(id),
  reference_no text,
  issued_on date,
  expires_on date,
  document_path text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on user_certifications (user_id);
create index on user_certifications (expires_on) where expires_on is not null;

create table notifications (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  kind text not null,
  title text not null,
  body text,
  payload jsonb not null default '{}'::jsonb,
  sent_at timestamptz,
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create index on notifications (user_id, created_at desc) where read_at is null;

-- Written by trigger on every business-significant table. Append-only; RLS
-- grants select and insert but never update or delete.
create table audit_log (
  id bigserial primary key,
  org_id uuid,
  table_name text not null,
  record_id uuid,
  actor_id uuid,
  action text not null,
  diff jsonb,
  at timestamptz not null default now()
);

create index on audit_log (table_name, record_id, at desc);
create index on audit_log (org_id, at desc);

-- Generic row auditor. Records only the fields that actually changed, so the
-- log stays readable rather than a wall of unchanged columns.
create or replace function audit_row()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_diff jsonb := '{}'::jsonb;
  v_key text;
  v_old jsonb;
  v_new jsonb;
begin
  if tg_op = 'INSERT' then
    v_new := to_jsonb(new);
    v_diff := jsonb_build_object('new', v_new);
  elsif tg_op = 'DELETE' then
    v_old := to_jsonb(old);
    v_diff := jsonb_build_object('old', v_old);
  else
    v_old := to_jsonb(old);
    v_new := to_jsonb(new);
    for v_key in select jsonb_object_keys(v_new) loop
      if v_key not in ('updated_at') and (v_old -> v_key) is distinct from (v_new -> v_key) then
        v_diff := v_diff || jsonb_build_object(
          v_key,
          jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key)
        );
      end if;
    end loop;
    if v_diff = '{}'::jsonb then
      return coalesce(new, old);
    end if;
  end if;

  insert into audit_log (org_id, table_name, record_id, actor_id, action, diff)
  values (
    coalesce((to_jsonb(coalesce(new, old)) ->> 'org_id')::uuid, null),
    tg_table_name,
    (to_jsonb(coalesce(new, old)) ->> 'id')::uuid,
    auth_user_id(),
    lower(tg_op),
    v_diff
  );

  return coalesce(new, old);
end;
$$;

create or replace function attach_audit(p_table text)
returns void
language plpgsql
as $$
begin
  execute format(
    'create trigger trg_%s_audit after insert or update or delete on %I
       for each row execute function audit_row()',
    p_table, p_table
  );
end;
$$;

select attach_audit('jobs');
select attach_audit('job_assignments');
select attach_audit('purchase_requests');
select attach_audit('purchase_request_lines');
select attach_audit('equipment_assignments');
select attach_audit('equipment_rentals');
select attach_audit('inventory_items');
select attach_audit('mileage_logs');
select attach_audit('time_entries');
select attach_audit('profiles');
select attach_audit('roles');

select attach_updated_at('certification_types');
select attach_updated_at('user_certifications');

-- ===========================================================
-- 0011_job_costing.sql
-- ===========================================================
-- 0011 Job costing
--
-- Derived from source rows rather than stored, so the costing model can be
-- reshaped later without migrating historical data.
--
-- This is the payoff for everything the field crew is asked to log. Without
-- it the logging reads as surveillance; with it the owner can see which
-- flat-quoted jobs actually made money.

create or replace function job_labour_cost(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(time_entry_hours(t) * coalesce(p.cost_rate, 0)), 0)
  from time_entries t
  join profiles p on p.id = t.user_id
  where t.job_id = p_job_id and t.clock_out_at is not null;
$$;

create or replace function job_material_cost(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(mu.quantity * i.average_cost), 0)
  from material_usage mu
  join inventory_items i on i.id = mu.item_id
  where mu.job_id = p_job_id;
$$;

-- Only approved lines count, and only on requests that were not rejected or
-- cancelled outright.
create or replace function job_purchase_cost(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(l.quantity * coalesce(l.estimated_unit_cost, 0)), 0)
  from purchase_request_lines l
  join purchase_requests r on r.id = l.request_id
  where r.job_id = p_job_id
    and l.line_status = 'approved'
    and r.status not in ('draft', 'rejected', 'cancelled');
$$;

create or replace function job_mileage_cost(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(
    sum(m.distance) * coalesce((o.settings ->> 'mileage_rate')::numeric, 0),
    0
  )
  from mileage_logs m
  join organizations o on o.id = m.org_id
  where m.job_id = p_job_id and m.is_business
  group by o.settings;
$$;

-- Owned equipment: days deployed against this job times the unit's internal
-- day rate. A placement still open is counted to now, so a job with a
-- scrubber sitting at the site keeps accruing cost and the margin visibly
-- erodes.
create or replace function job_equipment_cost(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(
    ceil(
      extract(epoch from (coalesce(a.ended_at, now()) - a.started_at)) / 86400.0
    ) * e.internal_day_rate
  ), 0)
  from equipment_assignments a
  join equipment e on e.id = a.equipment_id
  where a.job_id = p_job_id;
$$;

-- Rented equipment: the vendor's actual charge, falling back to the estimate
-- while the invoice is outstanding.
create or replace function job_rental_cost(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(coalesce(actual_cost, estimated_cost, 0)), 0)
  from equipment_rentals
  where job_id = p_job_id and status <> 'cancelled';
$$;

create view job_costs
with (security_invoker = true)
as
select
  j.id as job_id,
  j.org_id,
  j.job_number,
  j.title,
  j.status,
  j.customer_id,
  j.site_id,
  j.template_id,
  j.quoted_price,
  job_labour_cost(j.id)    as labour_cost,
  job_material_cost(j.id)  as material_cost,
  job_purchase_cost(j.id)  as purchase_cost,
  job_mileage_cost(j.id)   as mileage_cost,
  job_equipment_cost(j.id) as equipment_cost,
  job_rental_cost(j.id)    as rental_cost,
  (
    job_labour_cost(j.id) + job_material_cost(j.id) + job_purchase_cost(j.id)
    + job_mileage_cost(j.id) + job_equipment_cost(j.id) + job_rental_cost(j.id)
  ) as total_cost,
  (
    coalesce(j.quoted_price, 0) - (
      job_labour_cost(j.id) + job_material_cost(j.id) + job_purchase_cost(j.id)
      + job_mileage_cost(j.id) + job_equipment_cost(j.id) + job_rental_cost(j.id)
    )
  ) as margin
from jobs j
where j.deleted_at is null
  -- Margin is owner, manager and bookkeeper information, not field information.
  and has_permission('costing.view');

comment on view job_costs is
  'Per-job cost rollup against the flat quoted price. All components derived.';

-- ===========================================================
-- 0012_job_workflow.sql
-- ===========================================================
-- 0012 Job state machine, scheduling conflicts, acceptance and rescheduling
--
-- Legal transitions live in a table, not in branching code. Adding a status
-- later is a row, and every guard stays in one readable place.

create table job_transitions (
  from_status job_status not null,
  to_status job_status not null,
  required_permission text not null,
  guard text,
  primary key (from_status, to_status)
);

insert into job_transitions (from_status, to_status, required_permission, guard) values
  ('draft',         'scheduled',     'job.edit',        'scheduled'),
  ('scheduled',     'assigned',      'job.assign',      'assigned'),
  ('scheduled',     'cancelled',     'job.edit',        'reason'),
  ('assigned',      'accepted',      'job.accept',      'all_accepted'),
  ('assigned',      'scheduled',     'job.assign',      null),
  ('assigned',      'cancelled',     'job.edit',        'reason'),
  ('accepted',      'en_route',      'job.accept',      null),
  ('accepted',      'cancelled',     'job.edit',        'reason'),
  ('en_route',      'on_site',       'job.accept',      null),
  ('en_route',      'cancelled',     'job.edit',        'reason'),
  ('on_site',       'in_progress',   'job.accept',      null),
  ('on_site',       'blocked',       'job.accept',      'reason'),
  ('in_progress',   'blocked',       'job.accept',      'reason'),
  ('in_progress',   'work_complete', 'job.complete',    'completion'),
  ('in_progress',   'cancelled',     'job.edit',        'reason'),
  ('blocked',       'in_progress',   'job.accept',      null),
  ('blocked',       'cancelled',     'job.edit',        'reason'),
  ('work_complete', 'in_progress',   'job.review',      'reason'),
  ('work_complete', 'approved',      'job.review',      null),
  ('approved',      'closed',        'job.close',       null);

-- ---------------------------------------------------------------------------
-- Scheduling conflicts
-- ---------------------------------------------------------------------------

-- Returns the reasons a user cannot work the given window. Empty array means
-- no conflict. Surfaced at assignment time rather than discovered by a crew
-- standing in a driveway.
create or replace function scheduling_conflicts(
  p_user_id uuid,
  p_start timestamptz,
  p_end timestamptz,
  p_exclude_job_id uuid default null
)
returns text[]
language sql
stable
as $$
  select coalesce(array_agg(reason), '{}')
  from (
    select 'Approved time off (' || t.kind || ') ' ||
           to_char(t.starts_at, 'Mon DD') || ' to ' || to_char(t.ends_at, 'Mon DD') as reason
    from time_off t
    where t.user_id = p_user_id
      and t.status = 'approved'
      and tstzrange(t.starts_at, t.ends_at) && tstzrange(p_start, p_end)

    union all

    select 'Already assigned to ' || j.job_number || ' (' || j.title || ')' as reason
    from job_assignments a
    join jobs j on j.id = a.job_id
    left join job_visits v on v.id = a.visit_id
    where a.user_id = p_user_id
      and j.deleted_at is null
      and j.status not in ('cancelled', 'closed')
      and (p_exclude_job_id is null or j.id <> p_exclude_job_id)
      and tstzrange(
            coalesce(v.scheduled_start, j.scheduled_start),
            coalesce(v.scheduled_end, j.scheduled_end)
          ) && tstzrange(p_start, p_end)
  ) c;
$$;

-- Equipment of a given category free for the whole window. Used by the
-- scheduler so a scrubber staged at another site until Thursday is simply not
-- offered for a Wednesday job.
--
-- Custody and planning are different questions and are answered differently.
-- The exclusion constraint on equipment_assignments uses the ACTUAL end, so a
-- unit is in exactly one place until someone physically collects it. Planning
-- uses the EXPECTED end, so a scrubber due back tomorrow can be scheduled for
-- next week. equipment_overdue is what reconciles the two when reality lags
-- the plan.
create or replace function available_equipment(
  p_org_id uuid,
  p_category equipment_category,
  p_start timestamptz,
  p_end timestamptz
)
returns setof equipment
language sql
stable
as $$
  select e.*
  from equipment e
  where e.org_id = p_org_id
    and e.category = p_category
    and e.lifecycle_status = 'active'
    and not exists (
      select 1
      from equipment_assignments a
      where a.equipment_id = e.id
        and tstzrange(
              a.started_at,
              coalesce(a.ended_at, a.expected_end_at, 'infinity'::timestamptz)
            ) && tstzrange(p_start, p_end)
    );
$$;

-- ---------------------------------------------------------------------------
-- Completion gate
-- ---------------------------------------------------------------------------

-- Returns the list of outstanding requirements blocking work_complete. The
-- mobile completion screen renders this directly, so the gate directs rather
-- than merely refuses.
create or replace function job_completion_blockers(p_job_id uuid)
returns text[]
language plpgsql
stable
as $$
declare
  v_job jobs;
  v_req jsonb;
  v_blockers text[] := '{}';
  v_form jsonb;
begin
  select * into v_job from jobs where id = p_job_id;
  if v_job.id is null then
    return array['Job not found'];
  end if;

  select coalesce(t.completion_requirements, '{}'::jsonb) into v_req
  from job_templates t where t.id = v_job.template_id;
  v_req := coalesce(v_req, '{}'::jsonb);

  if coalesce((v_req ->> 'photos_before')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'before' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'Before photos required');
  end if;

  if coalesce((v_req ->> 'photos_after')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'after' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'After photos required');
  end if;

  if coalesce((v_req ->> 'customer_signature')::boolean, false)
     and not exists (
       select 1 from signatures where job_id = p_job_id and kind = 'completion'
     ) then
    v_blockers := array_append(v_blockers, 'Customer completion signature required');
  end if;

  -- Required forms are listed by template key.
  for v_form in select * from jsonb_array_elements(coalesce(v_req -> 'forms', '[]'::jsonb)) loop
    if not exists (
      select 1
      from form_submissions s
      join form_templates ft on ft.id = s.template_id
      where s.job_id = p_job_id
        and ft.key = (v_form #>> '{}')
        and s.is_complete
    ) then
      v_blockers := array_append(v_blockers, 'Form not complete: ' || (v_form #>> '{}'));
    end if;
  end loop;

  -- Everyone must be clocked out, or the labour cost for this job is wrong
  -- and the person stays on the clock overnight.
  if exists (
    select 1 from time_entries where job_id = p_job_id and clock_out_at is null
  ) then
    v_blockers := array_append(v_blockers, 'Open time entries — everyone must be clocked out');
  end if;

  -- The gate that stops air scrubbers being forgotten at finished jobs:
  -- equipment may remain on site only if a collection is actually scheduled.
  if exists (
    select 1
    from equipment_assignments a
    where a.job_id = p_job_id
      and a.kind = 'site_staging'
      and a.ended_at is null
      and a.expected_end_at is null
  ) then
    v_blockers := array_append(v_blockers,
      'Equipment still staged at site with no pickup scheduled');
  end if;

  if exists (
    select 1 from equipment_rentals
    where job_id = p_job_id
      and status in ('on_hire', 'overdue')
      and return_due_at is null
  ) then
    v_blockers := array_append(v_blockers, 'Rented equipment outstanding with no return date');
  end if;

  return v_blockers;
end;
$$;

-- ---------------------------------------------------------------------------
-- The one way a job status changes
-- ---------------------------------------------------------------------------

create or replace function transition_job(
  p_job_id uuid,
  p_to_status job_status,
  p_note text default null
)
returns jobs
language plpgsql
security definer
set search_path = public
as $$
declare
  v_job jobs;
  v_rule job_transitions;
  v_blockers text[];
  v_pending int;
begin
  select * into v_job from jobs where id = p_job_id and deleted_at is null
  for update;

  if v_job.id is null then
    raise exception 'Job % not found', p_job_id using errcode = 'P0002';
  end if;

  if v_job.status = p_to_status then
    return v_job;
  end if;

  select * into v_rule from job_transitions
  where from_status = v_job.status and to_status = p_to_status;

  if v_rule.from_status is null then
    raise exception 'Illegal job transition % -> %', v_job.status, p_to_status
      using errcode = 'check_violation';
  end if;

  if not has_permission(v_rule.required_permission) then
    raise exception 'Permission % required to move job % -> %',
      v_rule.required_permission, v_job.status, p_to_status
      using errcode = 'insufficient_privilege';
  end if;

  if v_rule.guard = 'reason' and (p_note is null or length(trim(p_note)) = 0) then
    raise exception 'A reason is required to move job % -> %', v_job.status, p_to_status
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'scheduled'
     and (v_job.scheduled_start is null or v_job.scheduled_end is null) then
    raise exception 'Job must have a scheduled window before it can be scheduled'
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'assigned'
     and not exists (select 1 from job_assignments where job_id = p_job_id) then
    raise exception 'Job must have at least one assignee'
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'all_accepted' then
    select count(*) into v_pending
    from job_assignments
    where job_id = p_job_id and acceptance_status <> 'accepted';
    if v_pending > 0 then
      raise exception '% assignee(s) have not accepted', v_pending
        using errcode = 'check_violation';
    end if;
  end if;

  if v_rule.guard = 'completion' then
    v_blockers := job_completion_blockers(p_job_id);
    if array_length(v_blockers, 1) > 0 then
      raise exception 'Job cannot be completed: %', array_to_string(v_blockers, '; ')
        using errcode = 'check_violation';
    end if;
  end if;

  update jobs
  set status = p_to_status,
      blocked_reason   = case when p_to_status = 'blocked' then p_note else null end,
      cancelled_reason = case when p_to_status = 'cancelled' then p_note else cancelled_reason end,
      actual_start = case
        when p_to_status = 'on_site' and actual_start is null then now()
        else actual_start end,
      actual_end = case
        when p_to_status = 'work_complete' then now()
        else actual_end end
  where id = p_job_id
  returning * into v_job;

  insert into job_status_history (org_id, job_id, from_status, to_status, changed_by, note)
  values (v_job.org_id, p_job_id, v_rule.from_status, p_to_status, auth_user_id(), p_note);

  return v_job;
end;
$$;

-- ---------------------------------------------------------------------------
-- Acceptance and rescheduling
-- ---------------------------------------------------------------------------

create or replace function accept_assignment(p_assignment_id uuid)
returns job_assignments
language plpgsql
security definer
set search_path = public
as $$
declare
  v_assignment job_assignments;
  v_pending int;
begin
  update job_assignments
  set acceptance_status = 'accepted', responded_at = now()
  where id = p_assignment_id
    and user_id = coalesce(auth_user_id(), user_id)
  returning * into v_assignment;

  if v_assignment.id is null then
    raise exception 'Assignment % not found for this user', p_assignment_id
      using errcode = 'P0002';
  end if;

  -- Once everyone has accepted, the job advances on its own.
  select count(*) into v_pending
  from job_assignments
  where job_id = v_assignment.job_id and acceptance_status <> 'accepted';

  if v_pending = 0 then
    perform transition_job(v_assignment.job_id, 'accepted');
  end if;

  return v_assignment;
end;
$$;

create or replace function request_reschedule(
  p_assignment_id uuid,
  p_reason text,
  p_proposed_start timestamptz default null,
  p_proposed_end timestamptz default null
)
returns reschedule_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_assignment job_assignments;
  v_request reschedule_requests;
begin
  if p_reason is null or length(trim(p_reason)) = 0 then
    raise exception 'A reason is required' using errcode = 'check_violation';
  end if;

  select * into v_assignment from job_assignments where id = p_assignment_id;
  if v_assignment.id is null then
    raise exception 'Assignment % not found', p_assignment_id using errcode = 'P0002';
  end if;

  update job_assignments
  set acceptance_status = 'reschedule_requested', responded_at = now()
  where id = p_assignment_id;

  insert into reschedule_requests (
    org_id, job_id, assignment_id, requested_by, reason, proposed_start, proposed_end
  )
  values (
    v_assignment.org_id, v_assignment.job_id, p_assignment_id,
    coalesce(auth_user_id(), v_assignment.user_id),
    p_reason, p_proposed_start, p_proposed_end
  )
  returning * into v_request;

  return v_request;
end;
$$;

create or replace function decide_reschedule(
  p_request_id uuid,
  p_approve boolean,
  p_reason text default null
)
returns reschedule_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request reschedule_requests;
  v_job jobs;
begin
  if not has_permission('reschedule.decide') then
    raise exception 'Permission reschedule.decide required'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_request from reschedule_requests where id = p_request_id for update;
  if v_request.id is null then
    raise exception 'Reschedule request % not found', p_request_id using errcode = 'P0002';
  end if;
  if v_request.status <> 'pending' then
    raise exception 'Request already %', v_request.status using errcode = 'check_violation';
  end if;

  if not p_approve and (p_reason is null or length(trim(p_reason)) = 0) then
    raise exception 'A reason is required to decline' using errcode = 'check_violation';
  end if;

  update reschedule_requests
  set status = case when p_approve then 'approved' else 'declined' end::reschedule_status,
      decided_by = auth_user_id(),
      decided_at = now(),
      decision_reason = p_reason
  where id = p_request_id
  returning * into v_request;

  if p_approve and v_request.proposed_start is not null then
    update jobs
    set scheduled_start = v_request.proposed_start,
        scheduled_end = coalesce(v_request.proposed_end, v_request.proposed_start)
    where id = v_request.job_id
    returning * into v_job;

    -- The move invalidates every acceptance, not just the requester's: the
    -- others agreed to a different time.
    update job_assignments
    set acceptance_status = 'pending', responded_at = null
    where job_id = v_request.job_id;

    if v_job.status in ('accepted', 'assigned') then
      update jobs set status = 'assigned' where id = v_request.job_id;
    end if;
  else
    update job_assignments
    set acceptance_status = 'pending'
    where id = v_request.assignment_id;
  end if;

  return v_request;
end;
$$;

-- ===========================================================
-- 0013_purchasing_workflow.sql
-- ===========================================================
-- 0013 Purchase request workflow, audit trigger, receipt into stock

-- ---------------------------------------------------------------------------
-- Append-only audit
--
-- Written by trigger rather than application code so nothing can bypass it.
-- RLS (0015) grants insert and select on the audit table but no update or
-- delete, to any role including the owner.
-- ---------------------------------------------------------------------------

create or replace function purchase_request_audit_trigger()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_old jsonb := to_jsonb(old);
  v_new jsonb := to_jsonb(new);
  v_key text;
  v_request_id uuid;
  v_line_id uuid;
  v_org uuid;
begin
  if tg_table_name = 'purchase_requests' then
    v_request_id := new.id;
    v_line_id := null;
    v_org := new.org_id;
    -- Drafts are the requester's scratch space; auditing starts at submit.
    if tg_op = 'UPDATE' and old.status = 'draft' and new.status = 'draft' then
      return new;
    end if;
  else
    v_request_id := new.request_id;
    v_line_id := new.id;
    v_org := new.org_id;
    if exists (
      select 1 from purchase_requests where id = new.request_id and status = 'draft'
    ) then
      return new;
    end if;
  end if;

  if tg_op = 'INSERT' then
    insert into purchase_request_audit (org_id, request_id, line_id, actor_id, action, field, new_value)
    values (v_org, v_request_id, v_line_id, auth_user_id(), tg_op, null, v_new::text);
    return new;
  end if;

  for v_key in select jsonb_object_keys(v_new) loop
    if v_key not in ('updated_at', 'created_at')
       and (v_old -> v_key) is distinct from (v_new -> v_key) then
      insert into purchase_request_audit (
        org_id, request_id, line_id, actor_id, action, field, old_value, new_value
      )
      values (
        v_org, v_request_id, v_line_id, auth_user_id(), 'update', v_key,
        v_old ->> v_key, v_new ->> v_key
      );
    end if;
  end loop;

  return new;
end;
$$;

create trigger trg_purchase_requests_pr_audit
  after insert or update on purchase_requests
  for each row execute function purchase_request_audit_trigger();

create trigger trg_purchase_request_lines_pr_audit
  after insert or update on purchase_request_lines
  for each row execute function purchase_request_audit_trigger();

-- Editing is locked on submit, not on approval. The requester can recall a
-- request to draft, but only while no approver has picked it up.
create or replace function purchase_request_lock_check()
returns trigger
language plpgsql
as $$
begin
  if tg_table_name = 'purchase_request_lines' then
    if exists (
      select 1 from purchase_requests r
      where r.id = coalesce(new.request_id, old.request_id)
        and r.status not in ('draft', 'under_review')
    ) then
      raise exception 'Lines cannot be changed once the request leaves draft or review'
        using errcode = 'check_violation';
    end if;
  end if;
  return coalesce(new, old);
end;
$$;

create trigger trg_purchase_request_lines_lock
  before insert or update or delete on purchase_request_lines
  for each row execute function purchase_request_lock_check();

-- ---------------------------------------------------------------------------
-- Transitions
-- ---------------------------------------------------------------------------

create or replace function submit_purchase_request(p_request_id uuid)
returns purchase_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request purchase_requests;
begin
  select * into v_request from purchase_requests where id = p_request_id for update;

  if v_request.id is null then
    raise exception 'Request % not found', p_request_id using errcode = 'P0002';
  end if;
  if v_request.status <> 'draft' then
    raise exception 'Only a draft can be submitted (currently %)', v_request.status
      using errcode = 'check_violation';
  end if;
  if not exists (select 1 from purchase_request_lines where request_id = p_request_id) then
    raise exception 'A request needs at least one line' using errcode = 'check_violation';
  end if;

  update purchase_requests
  set status = 'submitted', submitted_at = now()
  where id = p_request_id
  returning * into v_request;

  return v_request;
end;
$$;

create or replace function recall_purchase_request(p_request_id uuid)
returns purchase_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request purchase_requests;
begin
  select * into v_request from purchase_requests where id = p_request_id for update;

  if v_request.status <> 'submitted' then
    raise exception 'Only a submitted request can be recalled (currently %)', v_request.status
      using errcode = 'check_violation';
  end if;
  if v_request.requested_by <> coalesce(auth_user_id(), v_request.requested_by) then
    raise exception 'Only the requester can recall a request'
      using errcode = 'insufficient_privilege';
  end if;

  update purchase_requests set status = 'draft', submitted_at = null
  where id = p_request_id
  returning * into v_request;

  return v_request;
end;
$$;

-- Approve, partially approve, or reject. p_approved_line_ids null means
-- approve everything; a subset approves those and rejects the rest.
create or replace function decide_purchase_request(
  p_request_id uuid,
  p_approve boolean,
  p_reason text default null,
  p_approved_line_ids uuid[] default null
)
returns purchase_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request purchase_requests;
  v_total numeric;
  v_threshold numeric;
  v_approved_count int;
begin
  select * into v_request from purchase_requests where id = p_request_id for update;
  if v_request.id is null then
    raise exception 'Request % not found', p_request_id using errcode = 'P0002';
  end if;
  if v_request.status not in ('submitted', 'under_review') then
    raise exception 'Request is % and cannot be decided', v_request.status
      using errcode = 'check_violation';
  end if;

  if not has_permission('purchase.approve') then
    raise exception 'Permission purchase.approve required'
      using errcode = 'insufficient_privilege';
  end if;

  -- The threshold is read server-side. What a manager may approve is never
  -- decided by the client.
  select coalesce((settings ->> 'approval_threshold')::numeric, 0)
  into v_threshold
  from organizations where id = v_request.org_id;

  v_total := purchase_request_total(p_request_id);

  if p_approve
     and v_total > v_threshold
     and not has_permission('purchase.approve_unlimited') then
    raise exception
      'Request total % exceeds the approval threshold % — owner approval required',
      v_total, v_threshold
      using errcode = 'insufficient_privilege';
  end if;

  if not p_approve and (p_reason is null or length(trim(p_reason)) = 0) then
    raise exception 'A reason is required to reject' using errcode = 'check_violation';
  end if;

  if p_approve then
    if p_approved_line_ids is null then
      update purchase_request_lines set line_status = 'approved' where request_id = p_request_id;
    else
      update purchase_request_lines
      set line_status = case when id = any(p_approved_line_ids) then 'approved' else 'rejected' end,
          rejection_reason = case when id = any(p_approved_line_ids) then null else p_reason end
      where request_id = p_request_id;
    end if;

    select count(*) into v_approved_count
    from purchase_request_lines where request_id = p_request_id and line_status = 'approved';

    if v_approved_count = 0 then
      raise exception 'Approving with no approved lines — reject the request instead'
        using errcode = 'check_violation';
    end if;
  else
    update purchase_request_lines
    set line_status = 'rejected', rejection_reason = p_reason
    where request_id = p_request_id;
  end if;

  update purchase_requests
  set status = case when p_approve then 'approved' else 'rejected' end::purchase_status,
      decided_by = auth_user_id(),
      decided_at = now(),
      decision_reason = p_reason
  where id = p_request_id
  returning * into v_request;

  return v_request;
end;
$$;

-- Receiving is what keeps inventory worth believing: it writes the stock
-- movement and rolls the item's weighted average cost forward.
create or replace function receive_purchase_line(
  p_line_id uuid,
  p_quantity numeric,
  p_location_id uuid,
  p_actual_unit_cost numeric default null
)
returns purchase_request_lines
language plpgsql
security definer
set search_path = public
as $$
declare
  v_line purchase_request_lines;
  v_request purchase_requests;
  v_unit_cost numeric;
  v_on_hand numeric;
  v_outstanding int;
begin
  select * into v_line from purchase_request_lines where id = p_line_id for update;
  if v_line.id is null then
    raise exception 'Line % not found', p_line_id using errcode = 'P0002';
  end if;
  if v_line.line_status <> 'approved' then
    raise exception 'Only an approved line can be received' using errcode = 'check_violation';
  end if;
  if p_quantity <= 0 then
    raise exception 'Received quantity must be positive' using errcode = 'check_violation';
  end if;

  select * into v_request from purchase_requests where id = v_line.request_id for update;
  if v_request.status not in ('approved', 'ordered', 'partially_received') then
    raise exception 'Request is % and cannot receive stock', v_request.status
      using errcode = 'check_violation';
  end if;

  v_unit_cost := coalesce(p_actual_unit_cost, v_line.estimated_unit_cost, 0);

  if v_line.item_id is not null then
    insert into stock_movements (
      org_id, item_id, kind, to_location_id, quantity, unit_cost,
      job_id, reference_table, reference_id, created_by
    )
    values (
      v_line.org_id, v_line.item_id, 'receipt', p_location_id, p_quantity, v_unit_cost,
      v_request.job_id, 'purchase_request_lines', v_line.id, auth_user_id()
    );

    -- Weighted average across existing on-hand and the new receipt.
    select coalesce(sum(quantity), 0) into v_on_hand
    from stock_levels where item_id = v_line.item_id;

    update inventory_items
    set average_cost = case
      when v_on_hand <= 0 then v_unit_cost
      else round(
        ((average_cost * greatest(v_on_hand - p_quantity, 0)) + (v_unit_cost * p_quantity))
        / nullif(greatest(v_on_hand, p_quantity), 0), 4)
      end
    where id = v_line.item_id and v_unit_cost > 0;
  end if;

  update purchase_request_lines
  set received_quantity = received_quantity + p_quantity,
      receive_location_id = p_location_id
  where id = p_line_id
  returning * into v_line;

  select count(*) into v_outstanding
  from purchase_request_lines
  where request_id = v_line.request_id
    and line_status = 'approved'
    and received_quantity < quantity;

  update purchase_requests
  set status = case when v_outstanding = 0 then 'received' else 'partially_received' end::purchase_status
  where id = v_line.request_id;

  return v_line;
end;
$$;

-- ===========================================================
-- 0014_inventory_equipment_workflow.sql
-- ===========================================================
-- 0014 Material usage, mileage continuity, equipment placement workflow

-- ---------------------------------------------------------------------------
-- Material usage writes the ledger entry
-- ---------------------------------------------------------------------------

create or replace function material_usage_movement()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into stock_movements (
    org_id, item_id, kind, from_location_id, quantity,
    unit_cost, job_id, reference_table, reference_id, created_by
  )
  select
    new.org_id, new.item_id, 'usage', new.location_id, new.quantity,
    i.average_cost, new.job_id, 'material_usage', new.id, new.logged_by
  from inventory_items i where i.id = new.item_id;

  return new;
end;
$$;

create trigger trg_material_usage_movement
  after insert on material_usage
  for each row execute function material_usage_movement();

-- ---------------------------------------------------------------------------
-- Mileage: odometer continuity
--
-- A gap is recorded, not rejected. Vehicles get moved without a log, and a
-- hard block would simply stop people logging at all.
-- ---------------------------------------------------------------------------

create or replace function mileage_continuity()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_last numeric;
begin
  select current_odometer into v_last from vehicles where id = new.vehicle_id;

  if v_last is not null and new.odometer_start <> v_last then
    new.continuity_gap := new.odometer_start - v_last;
  else
    new.continuity_gap := null;
  end if;

  return new;
end;
$$;

create trigger trg_mileage_continuity
  before insert on mileage_logs
  for each row execute function mileage_continuity();

create or replace function mileage_advance_odometer()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update vehicles
  set current_odometer = greatest(current_odometer, new.odometer_end)
  where id = new.vehicle_id;
  return new;
end;
$$;

create trigger trg_mileage_advance_odometer
  after insert on mileage_logs
  for each row execute function mileage_advance_odometer();

-- ---------------------------------------------------------------------------
-- Equipment placement
--
-- Three verbs the field actually uses: stage, check out, collect. Moving
-- between sites is one call, so the old placement always closes as the new
-- one opens and the two can never overlap.
-- ---------------------------------------------------------------------------

create or replace function stage_equipment(
  p_equipment_id uuid,
  p_job_id uuid,
  p_site_id uuid,
  p_expected_end_at timestamptz default null,
  p_notes text default null
)
returns equipment_assignments
language plpgsql
security definer
set search_path = public
as $$
declare
  v_equipment equipment;
  v_open equipment_assignments;
  v_row equipment_assignments;
begin
  select * into v_equipment from equipment where id = p_equipment_id for update;
  if v_equipment.id is null then
    raise exception 'Equipment % not found', p_equipment_id using errcode = 'P0002';
  end if;
  if v_equipment.lifecycle_status <> 'active' then
    raise exception 'Equipment % is %', v_equipment.asset_tag, v_equipment.lifecycle_status
      using errcode = 'check_violation';
  end if;

  -- Close any open placement first. This is what makes "move it to this
  -- site" a single scan for the person holding the unit.
  select * into v_open from equipment_assignments
  where equipment_id = p_equipment_id and ended_at is null
  for update;

  if v_open.id is not null then
    update equipment_assignments
    set ended_at = now(), collected_by = auth_user_id()
    where id = v_open.id;
  end if;

  insert into equipment_assignments (
    org_id, equipment_id, kind, job_id, site_id,
    started_at, expected_end_at, placed_by, notes
  )
  values (
    v_equipment.org_id, p_equipment_id, 'site_staging', p_job_id, p_site_id,
    now(), p_expected_end_at, auth_user_id(), p_notes
  )
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function checkout_equipment(
  p_equipment_id uuid,
  p_user_id uuid,
  p_job_id uuid default null,
  p_expected_end_at timestamptz default null
)
returns equipment_assignments
language plpgsql
security definer
set search_path = public
as $$
declare
  v_equipment equipment;
  v_open equipment_assignments;
  v_row equipment_assignments;
begin
  select * into v_equipment from equipment where id = p_equipment_id for update;
  if v_equipment.id is null then
    raise exception 'Equipment % not found', p_equipment_id using errcode = 'P0002';
  end if;
  if v_equipment.lifecycle_status <> 'active' then
    raise exception 'Equipment % is %', v_equipment.asset_tag, v_equipment.lifecycle_status
      using errcode = 'check_violation';
  end if;

  select * into v_open from equipment_assignments
  where equipment_id = p_equipment_id and ended_at is null;

  -- Checking out a unit that is staged at a site would silently pull it off
  -- a running job, so this one refuses rather than reassigning.
  if v_open.id is not null then
    raise exception 'Equipment % is currently % — collect it first',
      v_equipment.asset_tag, v_open.kind
      using errcode = 'check_violation';
  end if;

  insert into equipment_assignments (
    org_id, equipment_id, kind, job_id, assigned_to_user_id,
    started_at, expected_end_at, placed_by
  )
  values (
    v_equipment.org_id, p_equipment_id, 'checkout', p_job_id, p_user_id,
    now(), p_expected_end_at, auth_user_id()
  )
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function collect_equipment(
  p_equipment_id uuid,
  p_condition equipment_condition default 'ok',
  p_runtime_hours numeric default null,
  p_notes text default null
)
returns equipment_assignments
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row equipment_assignments;
begin
  update equipment_assignments
  set ended_at = now(),
      collected_by = auth_user_id(),
      condition_in = p_condition,
      notes = coalesce(p_notes, notes)
  where equipment_id = p_equipment_id and ended_at is null
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Equipment % is not currently placed', p_equipment_id
      using errcode = 'P0002';
  end if;

  if p_runtime_hours is not null then
    insert into equipment_runtime_logs (org_id, equipment_id, job_id, reading_hours, read_by)
    values (v_row.org_id, p_equipment_id, v_row.job_id, p_runtime_hours, auth_user_id());
  end if;

  -- A unit that came back damaged should not be schedulable until someone
  -- looks at it.
  if p_condition = 'needs_service' then
    update equipment set lifecycle_status = 'in_maintenance' where id = p_equipment_id;
  end if;

  return v_row;
end;
$$;

-- Everything past its expected collection or return date, owned and rented
-- together. This is the morning list.
create view equipment_overdue
with (security_invoker = true)
as
select
  'owned'::text        as source,
  e.asset_tag          as reference,
  e.name               as description,
  a.org_id,
  a.job_id,
  a.site_id,
  a.expected_end_at    as due_at,
  extract(epoch from (now() - a.expected_end_at)) / 86400.0 as days_overdue
from equipment_assignments a
join equipment e on e.id = a.equipment_id
where a.ended_at is null
  and a.expected_end_at is not null
  and a.expected_end_at < now()

union all

select
  'rental'::text,
  coalesce(r.agreement_no, 'rental'),
  r.description,
  r.org_id,
  r.job_id,
  r.site_id,
  r.return_due_at,
  extract(epoch from (now() - r.return_due_at)) / 86400.0
from equipment_rentals r
where r.returned_at is null
  and r.return_due_at is not null
  and r.return_due_at < now()
  and r.status not in ('cancelled', 'returned', 'closed');

-- Deployed days against available days. Answers "do we need another scrubber
-- or are three of them sitting idle".
create or replace function equipment_utilisation(
  p_org_id uuid,
  p_from timestamptz,
  p_to timestamptz
)
returns table (
  equipment_id uuid,
  asset_tag text,
  name text,
  category equipment_category,
  deployed_days numeric,
  window_days numeric,
  utilisation_pct numeric
)
language sql
stable
as $$
  select
    e.id,
    e.asset_tag,
    e.name,
    e.category,
    round(coalesce(sum(
      extract(epoch from (
        least(coalesce(a.ended_at, p_to), p_to) - greatest(a.started_at, p_from)
      )) / 86400.0
    ), 0)::numeric, 2) as deployed_days,
    round((extract(epoch from (p_to - p_from)) / 86400.0)::numeric, 2) as window_days,
    round((coalesce(sum(
      extract(epoch from (
        least(coalesce(a.ended_at, p_to), p_to) - greatest(a.started_at, p_from)
      )) / 86400.0
    ), 0) / nullif(extract(epoch from (p_to - p_from)) / 86400.0, 0) * 100)::numeric, 1)
  from equipment e
  left join equipment_assignments a
    on a.equipment_id = e.id
   and tstzrange(a.started_at, coalesce(a.ended_at, 'infinity'::timestamptz))
       && tstzrange(p_from, p_to)
  where e.org_id = p_org_id and e.lifecycle_status = 'active'
  group by e.id, e.asset_tag, e.name, e.category;
$$;

-- ===========================================================
-- 0015_rls.sql
-- ===========================================================
-- 0015 Row level security
--
-- The permission matrix in docs/04-permissions.md is enforced here, in the
-- database, not in the clients. A technician calling the REST endpoint
-- directly must not be able to approve a purchase request, and that guarantee
-- cannot live in a React component.

-- Every table is org-scoped and denies by default; policies open specific
-- doors from there.
create or replace function enable_rls(p_table text)
returns void
language plpgsql
as $$
begin
  execute format('alter table %I enable row level security', p_table);
  execute format('alter table %I force row level security', p_table);
end;
$$;

do $$
declare t text;
begin
  foreach t in array array[
    'organizations','roles','profiles','crews','crew_members','time_off',
    'customers','sites','job_templates','jobs','job_visits','job_assignments',
    'job_status_history','reschedule_requests','job_comments','job_documents',
    'time_entries','job_photos','form_templates','form_submissions','signatures',
    'suppliers','inventory_items','stock_locations','stock_movements','material_usage',
    'purchase_requests','purchase_request_lines','purchase_request_audit',
    'vehicles','mileage_logs','fuel_logs','vehicle_maintenance',
    'equipment','equipment_assignments','equipment_rentals',
    'equipment_runtime_logs','equipment_maintenance',
    'certification_types','user_certifications','notifications','audit_log'
  ] loop
    perform enable_rls(t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Helper: does the caller have a stake in this job?
-- ---------------------------------------------------------------------------

create or replace function can_see_job(p_job_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select has_permission('job.view_all')
      or exists (
        select 1 from job_assignments a
        where a.job_id = p_job_id and a.user_id = auth_user_id()
      )
      or exists (
        -- A crew lead sees the whole crew's work, not only their own row.
        select 1
        from job_assignments a
        join crew_members cm on cm.crew_id = a.crew_id
        join crews c on c.id = a.crew_id
        where a.job_id = p_job_id
          and c.lead_user_id = auth_user_id()
          and cm.user_id is not null
      );
$$;

-- ---------------------------------------------------------------------------
-- Org-wide reference data: readable by the whole org, writable with a flag
-- ---------------------------------------------------------------------------

do $$
declare
  t text;
  write_flag text;
begin
  foreach t in array array[
    'customers','sites','job_templates','suppliers','inventory_items',
    'stock_locations','vehicles','equipment','form_templates','certification_types',
    'crews','roles'
  ] loop
    write_flag := case t
      when 'customers' then 'customer.manage'
      when 'sites' then 'customer.manage'
      when 'job_templates' then 'job.manage_templates'
      when 'suppliers' then 'inventory.manage'
      when 'inventory_items' then 'inventory.manage'
      when 'stock_locations' then 'inventory.manage'
      when 'vehicles' then 'vehicle.manage'
      when 'equipment' then 'equipment.manage'
      when 'form_templates' then 'job.manage_templates'
      when 'certification_types' then 'user.manage'
      when 'crews' then 'user.manage'
      when 'roles' then 'role.manage'
    end;

    execute format($p$
      create policy %1$s_select on %1$I for select
        using (org_id = auth_org_id());
    $p$, t);

    execute format($p$
      create policy %1$s_write on %1$I for all
        using (org_id = auth_org_id() and has_permission(%2$L))
        with check (org_id = auth_org_id() and has_permission(%2$L));
    $p$, t, write_flag);
  end loop;
end $$;

-- crew_members carries no org_id of its own; it is scoped through its crew.
create policy crew_members_select on crew_members for select
  using (exists (select 1 from crews c where c.id = crew_id and c.org_id = auth_org_id()));
create policy crew_members_write on crew_members for all
  using (
    has_permission('user.manage')
    and exists (select 1 from crews c where c.id = crew_id and c.org_id = auth_org_id())
  )
  with check (
    has_permission('user.manage')
    and exists (select 1 from crews c where c.id = crew_id and c.org_id = auth_org_id())
  );

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------

create policy organizations_select on organizations for select
  using (id = auth_org_id());
create policy organizations_update on organizations for update
  using (id = auth_org_id() and has_permission('org.manage_settings'))
  with check (id = auth_org_id() and has_permission('org.manage_settings'));

-- Everyone can see who their colleagues are; cost_rate is protected by the
-- profiles_safe view rather than by hiding the row.
create policy profiles_select on profiles for select
  using (org_id = auth_org_id());
create policy profiles_self_update on profiles for update
  using (id = auth_user_id())
  with check (id = auth_user_id());
create policy profiles_admin_write on profiles for all
  using (org_id = auth_org_id() and has_permission('user.manage'))
  with check (org_id = auth_org_id() and has_permission('user.manage'));

-- cost_rate is owner-only. Exposing the column through a view keeps the
-- underlying row readable for names and phone numbers.
create view profiles_safe
with (security_invoker = true)
as
select
  id, org_id, role_id, full_name, email, phone, is_active, created_at,
  case when has_permission('user.view_cost_rates') then cost_rate else null end as cost_rate
from profiles;

create policy time_off_select on time_off for select
  using (org_id = auth_org_id() and (user_id = auth_user_id() or has_permission('timeoff.manage')));
create policy time_off_insert on time_off for insert
  with check (org_id = auth_org_id() and user_id = auth_user_id());
create policy time_off_manage on time_off for all
  using (org_id = auth_org_id() and has_permission('timeoff.manage'))
  with check (org_id = auth_org_id() and has_permission('timeoff.manage'));

-- ---------------------------------------------------------------------------
-- Jobs
-- ---------------------------------------------------------------------------

create policy jobs_select on jobs for select
  using (org_id = auth_org_id() and can_see_job(id));
create policy jobs_write on jobs for all
  using (org_id = auth_org_id() and has_permission('job.edit'))
  with check (org_id = auth_org_id() and has_permission('job.edit'));

create policy job_visits_select on job_visits for select
  using (org_id = auth_org_id() and can_see_job(job_id));
create policy job_visits_write on job_visits for all
  using (org_id = auth_org_id() and has_permission('job.edit'))
  with check (org_id = auth_org_id() and has_permission('job.edit'));

create policy job_assignments_select on job_assignments for select
  using (org_id = auth_org_id() and (user_id = auth_user_id() or can_see_job(job_id)));
-- Assignees update only their own acceptance; the transition functions are
-- security definer and bypass this for the legal moves.
create policy job_assignments_self_update on job_assignments for update
  using (user_id = auth_user_id())
  with check (user_id = auth_user_id());
create policy job_assignments_write on job_assignments for all
  using (org_id = auth_org_id() and has_permission('job.assign'))
  with check (org_id = auth_org_id() and has_permission('job.assign'));

-- Append-only: select and insert, never update or delete, for anyone.
create policy job_status_history_select on job_status_history for select
  using (org_id = auth_org_id() and can_see_job(job_id));
create policy job_status_history_insert on job_status_history for insert
  with check (org_id = auth_org_id());

create policy reschedule_select on reschedule_requests for select
  using (org_id = auth_org_id() and (requested_by = auth_user_id() or has_permission('reschedule.decide')));
create policy reschedule_insert on reschedule_requests for insert
  with check (org_id = auth_org_id() and requested_by = auth_user_id());
create policy reschedule_decide on reschedule_requests for update
  using (org_id = auth_org_id() and has_permission('reschedule.decide'))
  with check (org_id = auth_org_id() and has_permission('reschedule.decide'));

create policy job_comments_select on job_comments for select
  using (org_id = auth_org_id() and can_see_job(job_id));
create policy job_comments_insert on job_comments for insert
  with check (org_id = auth_org_id() and author_id = auth_user_id() and can_see_job(job_id));
create policy job_comments_own_update on job_comments for update
  using (author_id = auth_user_id())
  with check (author_id = auth_user_id());

create policy job_documents_select on job_documents for select
  using (org_id = auth_org_id());
create policy job_documents_write on job_documents for all
  using (org_id = auth_org_id() and has_permission('job.edit'))
  with check (org_id = auth_org_id());

-- ---------------------------------------------------------------------------
-- Field capture: log your own work, managers see and correct everything
-- ---------------------------------------------------------------------------

create policy time_entries_select on time_entries for select
  using (org_id = auth_org_id() and (user_id = auth_user_id() or has_permission('time.view_all')));
create policy time_entries_self on time_entries for insert
  with check (org_id = auth_org_id() and (user_id = auth_user_id() or has_permission('time.log_others')));
create policy time_entries_self_update on time_entries for update
  using (user_id = auth_user_id() and clock_out_at is null)
  with check (user_id = auth_user_id());
create policy time_entries_manage on time_entries for all
  using (org_id = auth_org_id() and has_permission('time.edit_all'))
  with check (org_id = auth_org_id() and has_permission('time.edit_all'));

create policy job_photos_select on job_photos for select
  using (org_id = auth_org_id() and can_see_job(job_id));
create policy job_photos_insert on job_photos for insert
  with check (org_id = auth_org_id() and can_see_job(job_id));
create policy job_photos_manage on job_photos for all
  using (org_id = auth_org_id() and has_permission('job.edit'))
  with check (org_id = auth_org_id() and has_permission('job.edit'));

create policy form_submissions_select on form_submissions for select
  using (org_id = auth_org_id() and can_see_job(job_id));
create policy form_submissions_write on form_submissions for all
  using (org_id = auth_org_id() and can_see_job(job_id))
  with check (org_id = auth_org_id() and can_see_job(job_id));

create policy signatures_select on signatures for select
  using (org_id = auth_org_id() and can_see_job(job_id));
create policy signatures_insert on signatures for insert
  with check (org_id = auth_org_id() and can_see_job(job_id));

-- ---------------------------------------------------------------------------
-- Inventory
-- ---------------------------------------------------------------------------

create policy stock_movements_select on stock_movements for select
  using (org_id = auth_org_id());
-- Adjustments and counts need the flag; usage and transfers are field work.
create policy stock_movements_insert on stock_movements for insert
  with check (
    org_id = auth_org_id()
    and (
      (kind in ('usage', 'receipt') and has_permission('inventory.log_usage'))
      or (kind = 'transfer' and has_permission('inventory.transfer'))
      or (kind in ('adjustment', 'count', 'return') and has_permission('inventory.adjust'))
    )
  );

create policy material_usage_select on material_usage for select
  using (org_id = auth_org_id() and can_see_job(job_id));
create policy material_usage_insert on material_usage for insert
  with check (org_id = auth_org_id() and can_see_job(job_id));

-- ---------------------------------------------------------------------------
-- Purchasing
-- ---------------------------------------------------------------------------

create policy purchase_requests_select on purchase_requests for select
  using (
    org_id = auth_org_id()
    and (requested_by = auth_user_id() or assigned_to = auth_user_id()
         or has_permission('purchase.view_all'))
  );
create policy purchase_requests_insert on purchase_requests for insert
  with check (org_id = auth_org_id() and requested_by = auth_user_id());
-- The requester edits their own draft only; approvers edit under review.
create policy purchase_requests_own_draft on purchase_requests for update
  using (requested_by = auth_user_id() and status = 'draft')
  with check (requested_by = auth_user_id());
create policy purchase_requests_approver on purchase_requests for update
  using (org_id = auth_org_id() and has_permission('purchase.approve'))
  with check (org_id = auth_org_id() and has_permission('purchase.approve'));

create policy purchase_lines_select on purchase_request_lines for select
  using (
    org_id = auth_org_id()
    and exists (
      select 1 from purchase_requests r
      where r.id = request_id
        and (r.requested_by = auth_user_id() or r.assigned_to = auth_user_id()
             or has_permission('purchase.view_all'))
    )
  );
create policy purchase_lines_write on purchase_request_lines for all
  using (
    org_id = auth_org_id()
    and exists (
      select 1 from purchase_requests r
      where r.id = request_id
        and (
          (r.requested_by = auth_user_id() and r.status = 'draft')
          or has_permission('purchase.approve')
        )
    )
  )
  with check (org_id = auth_org_id());

-- The edit history. Insert and select only: no update or delete policy is
-- defined, for any role, including the owner. This is deliberate.
create policy purchase_audit_select on purchase_request_audit for select
  using (org_id = auth_org_id() and has_permission('purchase.view_history'));
create policy purchase_audit_insert on purchase_request_audit for insert
  with check (org_id = auth_org_id());

-- ---------------------------------------------------------------------------
-- Vehicles
-- ---------------------------------------------------------------------------

create policy mileage_select on mileage_logs for select
  using (org_id = auth_org_id() and (user_id = auth_user_id() or has_permission('mileage.view_all')));
create policy mileage_insert on mileage_logs for insert
  with check (org_id = auth_org_id() and user_id = auth_user_id());
create policy mileage_manage on mileage_logs for all
  using (org_id = auth_org_id() and has_permission('mileage.edit_all'))
  with check (org_id = auth_org_id() and has_permission('mileage.edit_all'));

create policy fuel_select on fuel_logs for select using (org_id = auth_org_id());
create policy fuel_insert on fuel_logs for insert with check (org_id = auth_org_id());
create policy fuel_manage on fuel_logs for all
  using (org_id = auth_org_id() and has_permission('vehicle.manage'))
  with check (org_id = auth_org_id() and has_permission('vehicle.manage'));

create policy vehicle_maint_select on vehicle_maintenance for select
  using (org_id = auth_org_id());
create policy vehicle_maint_write on vehicle_maintenance for all
  using (org_id = auth_org_id() and has_permission('vehicle.manage'))
  with check (org_id = auth_org_id() and has_permission('vehicle.manage'));

-- ---------------------------------------------------------------------------
-- Equipment: anyone in the field may move a unit, only managers may create
-- rental agreements or enter cost
-- ---------------------------------------------------------------------------

create policy equipment_assignments_select on equipment_assignments for select
  using (org_id = auth_org_id());
create policy equipment_assignments_field on equipment_assignments for all
  using (org_id = auth_org_id() and has_permission('equipment.place'))
  with check (org_id = auth_org_id() and has_permission('equipment.place'));

create policy equipment_rentals_select on equipment_rentals for select
  using (org_id = auth_org_id());
create policy equipment_rentals_write on equipment_rentals for all
  using (org_id = auth_org_id() and has_permission('equipment.rental_manage'))
  with check (org_id = auth_org_id() and has_permission('equipment.rental_manage'));

create policy equipment_runtime_select on equipment_runtime_logs for select
  using (org_id = auth_org_id());
create policy equipment_runtime_insert on equipment_runtime_logs for insert
  with check (org_id = auth_org_id() and has_permission('equipment.place'));

create policy equipment_maint_select on equipment_maintenance for select
  using (org_id = auth_org_id());
create policy equipment_maint_write on equipment_maintenance for all
  using (org_id = auth_org_id() and has_permission('equipment.manage'))
  with check (org_id = auth_org_id() and has_permission('equipment.manage'));

-- ---------------------------------------------------------------------------
-- Compliance, notifications, audit
-- ---------------------------------------------------------------------------

create policy user_certs_select on user_certifications for select
  using (org_id = auth_org_id() and (user_id = auth_user_id() or has_permission('user.manage')));
create policy user_certs_write on user_certifications for all
  using (org_id = auth_org_id() and has_permission('user.manage'))
  with check (org_id = auth_org_id() and has_permission('user.manage'));

create policy notifications_select on notifications for select
  using (user_id = auth_user_id());
create policy notifications_update on notifications for update
  using (user_id = auth_user_id())
  with check (user_id = auth_user_id());
create policy notifications_insert on notifications for insert
  with check (org_id = auth_org_id());

-- Append-only, same as the purchase audit: select and insert, nothing else.
create policy audit_log_select on audit_log for select
  using (org_id = auth_org_id() and has_permission('audit.view'));
create policy audit_log_insert on audit_log for insert
  with check (true);

-- ===========================================================
-- 0016_default_roles.sql
-- ===========================================================
-- 0016 Default roles and org provisioning
--
-- Roles are per-organisation rows so an owner can adjust one flag without a
-- deployment. These are the starting five from docs/04-permissions.md.

create or replace function provision_org_roles(p_org_id uuid)
returns void
language plpgsql
as $$
begin
  insert into roles (org_id, key, name, is_system, permissions) values
  (p_org_id, 'owner', 'Owner', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.close', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.approve_unlimited', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'user.view_cost_rates', true,
    'role.manage', true, 'org.manage_settings', true, 'audit.view', true,
    'costing.view', true, 'export.run', true
  )),

  -- Manager: everything operational, spend capped by the org threshold
  -- (purchase.approve_unlimited is what lifts the cap, and only the owner
  -- has it).
  (p_org_id, 'manager', 'Manager', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'audit.view', true,
    'costing.view', true, 'export.run', true
  )),

  -- Crew lead: runs a crew on site, logs for the crew, approves nothing.
  (p_org_id, 'crew_lead', 'Crew Lead', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'inventory.log_usage', true, 'inventory.transfer', true,
    'equipment.place', true,
    'time.log_others', true
  )),

  (p_org_id, 'technician', 'Technician', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'inventory.log_usage', true,
    'equipment.place', true
  )),

  (p_org_id, 'bookkeeper', 'Bookkeeper', true, jsonb_build_object(
    'job.view_all', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'mileage.view_all', true, 'time.view_all', true,
    'audit.view', true, 'costing.view', true, 'export.run', true,
    'job.close', true
  ))
  on conflict (org_id, key) do nothing;
end;
$$;

-- Starting checklists and reading sheets for mold remediation work.
create or replace function provision_org_forms(p_org_id uuid)
returns void
language plpgsql
as $$
begin
  insert into form_templates (org_id, key, name, description, is_per_room, fields) values
  (p_org_id, 'moisture_readings', 'Moisture Readings', 'Per-room moisture and psychrometric readings', true,
   '[
     {"key":"material","label":"Material","type":"select","required":true,
      "options":["Drywall","Wood framing","Subfloor","Concrete","Insulation","Other"]},
     {"key":"moisture_pct","label":"Moisture content","type":"number","unit":"%","required":true},
     {"key":"temp_f","label":"Temperature","type":"number","unit":"F","required":true},
     {"key":"rh_pct","label":"Relative humidity","type":"number","unit":"%","required":true},
     {"key":"gpp","label":"Grains per pound","type":"number","unit":"gpp","required":false},
     {"key":"notes","label":"Notes","type":"text","required":false}
   ]'::jsonb),

  (p_org_id, 'containment_check', 'Containment Verification', 'Containment and negative pressure check', false,
   '[
     {"key":"barrier_intact","label":"Barrier intact","type":"boolean","required":true},
     {"key":"negative_pressure","label":"Negative pressure confirmed","type":"boolean","required":true},
     {"key":"pressure_reading","label":"Pressure differential","type":"number","unit":"inWC","required":false},
     {"key":"scrubbers_running","label":"Air scrubbers running","type":"number","required":true},
     {"key":"decon_setup","label":"Decontamination chamber set up","type":"boolean","required":true},
     {"key":"notes","label":"Notes","type":"text","required":false}
   ]'::jsonb),

  (p_org_id, 'ppe_safety', 'PPE and Job Hazard Check', 'Pre-work safety check', false,
   '[
     {"key":"respirator","label":"Respirator worn and fit-tested","type":"boolean","required":true},
     {"key":"suit","label":"Protective suit","type":"boolean","required":true},
     {"key":"gloves_eyes","label":"Gloves and eye protection","type":"boolean","required":true},
     {"key":"hazards","label":"Hazards identified","type":"text","required":true},
     {"key":"electrical_safe","label":"Electrical hazards controlled","type":"boolean","required":true},
     {"key":"walkthrough_done","label":"Crew walkthrough completed","type":"boolean","required":true}
   ]'::jsonb),

  (p_org_id, 'chain_of_custody', 'Sample Chain of Custody', 'Air and surface sample tracking', false,
   '[
     {"key":"sample_id","label":"Sample ID","type":"text","required":true},
     {"key":"sample_type","label":"Sample type","type":"select","required":true,
      "options":["Air - indoor","Air - outdoor control","Surface tape","Surface swab","Bulk"]},
     {"key":"location","label":"Sample location","type":"text","required":true},
     {"key":"collected_at","label":"Collected at","type":"datetime","required":true},
     {"key":"lab","label":"Lab","type":"text","required":true},
     {"key":"released_to","label":"Released to","type":"text","required":true}
   ]'::jsonb)
  on conflict (org_id, key) do nothing;
end;
$$;

create or replace function provision_org(p_org_id uuid)
returns void
language plpgsql
as $$
begin
  perform provision_org_roles(p_org_id);
  perform provision_org_forms(p_org_id);
end;
$$;

comment on function provision_org(uuid) is
  'Creates the default roles and form templates for a new organisation.';

-- ===========================================================
-- 0017_change_orders.sql
-- ===========================================================
-- 0017 Change orders
--
-- Every job is billed flat, direct to the customer, with no insurer absorbing
-- overruns. So when scope grows mid-job — more rooms affected than the
-- inspection found, rot behind a wall — the extra work is either agreed and
-- priced, or it is done for free. There is no third outcome.
--
-- A change order is that agreement: extra scope, a price, and the customer's
-- decision recorded. The contract price is then derived from the base quote
-- plus approved change orders, so the original quote stays visible and the
-- growth is auditable.

create type change_order_status as enum (
  'draft', 'presented', 'approved', 'rejected', 'cancelled'
);

-- How the customer's agreement was captured. Residential work is often agreed
-- verbally on site; recording which is which matters if it is ever disputed.
create type change_order_approval as enum ('signature', 'verbal', 'written');

create table change_orders (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  job_id uuid not null references jobs(id) on delete cascade,
  seq int not null,
  title text not null,
  -- What was found and what it takes to put right, in language the customer
  -- will read.
  description text not null,
  -- Negative is legitimate: a descope credit is a change order too.
  amount numeric(12,2),
  added_hours numeric(6,2),
  status change_order_status not null default 'draft',
  presented_at timestamptz,
  decided_at timestamptz,
  approval_method change_order_approval,
  -- Whoever agreed on the customer's side, however it was captured.
  customer_name text,
  signature_id uuid references signatures(id),
  decision_reason text,
  created_by uuid references profiles(id),
  presented_by uuid references profiles(id),
  recorded_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (job_id, seq),
  -- A presented change order must carry a price; "we'll sort it out later" is
  -- how the margin disappears.
  constraint change_order_priced check (
    status = 'draft' or status = 'cancelled' or amount is not null
  ),
  constraint change_order_signature_present check (
    approval_method is distinct from 'signature' or signature_id is not null
  ),
  constraint change_order_verbal_named check (
    approval_method is distinct from 'verbal'
      or (customer_name is not null and length(trim(customer_name)) > 0)
  )
);

create index on change_orders (job_id, seq);
create index on change_orders (org_id, status) where status = 'presented';

create table change_order_photos (
  change_order_id uuid not null references change_orders(id) on delete cascade,
  photo_id uuid not null references job_photos(id) on delete cascade,
  primary key (change_order_id, photo_id)
);

select attach_updated_at('change_orders');
select attach_audit('change_orders');

-- Per-job numbering: CO-1, CO-2. Assigned server-side so two people drafting
-- at once cannot collide.
create or replace function change_order_assign_seq()
returns trigger
language plpgsql
as $$
begin
  if new.seq is null or new.seq = 0 then
    select coalesce(max(seq), 0) + 1 into new.seq
    from change_orders where job_id = new.job_id;
  end if;
  return new;
end;
$$;

create trigger trg_change_orders_seq
  before insert on change_orders
  for each row execute function change_order_assign_seq();

alter table change_orders alter column seq set default 0;

-- ---------------------------------------------------------------------------
-- Derived contract price
-- ---------------------------------------------------------------------------

comment on column jobs.quoted_price is
  'The BASE quoted price. The amount actually owed is job_contract_price(), '
  'which adds approved change orders.';

create or replace function job_change_order_total(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(amount), 0)
  from change_orders
  where job_id = p_job_id and status = 'approved';
$$;

create or replace function job_contract_price(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce((select quoted_price from jobs where id = p_job_id), 0)
       + job_change_order_total(p_job_id);
$$;

-- Money agreed but not yet decided by the customer. Surfaced so a job is not
-- closed with an open question hanging over it.
create or replace function job_pending_change_order_total(p_job_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(amount), 0)
  from change_orders
  where job_id = p_job_id and status = 'presented';
$$;

-- ---------------------------------------------------------------------------
-- Workflow
-- ---------------------------------------------------------------------------

-- The crew lead on site finds the extra damage and drafts it, with photos.
-- Pricing and presenting is the manager's, which is why the flags differ.
create or replace function present_change_order(
  p_change_order_id uuid,
  p_amount numeric default null
)
returns change_orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_co change_orders;
begin
  if not has_permission('changeorder.manage') then
    raise exception 'Permission changeorder.manage required'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_co from change_orders where id = p_change_order_id for update;
  if v_co.id is null then
    raise exception 'Change order % not found', p_change_order_id using errcode = 'P0002';
  end if;
  if v_co.status <> 'draft' then
    raise exception 'Only a draft change order can be presented (currently %)', v_co.status
      using errcode = 'check_violation';
  end if;
  if coalesce(p_amount, v_co.amount) is null then
    raise exception 'A change order needs a price before it is presented'
      using errcode = 'check_violation';
  end if;

  update change_orders
  set amount = coalesce(p_amount, amount),
      status = 'presented',
      presented_at = now(),
      presented_by = auth_user_id()
  where id = p_change_order_id
  returning * into v_co;

  return v_co;
end;
$$;

create or replace function decide_change_order(
  p_change_order_id uuid,
  p_approve boolean,
  p_method change_order_approval default 'verbal',
  p_customer_name text default null,
  p_signature_id uuid default null,
  p_reason text default null
)
returns change_orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_co change_orders;
begin
  if not has_permission('changeorder.manage') then
    raise exception 'Permission changeorder.manage required'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_co from change_orders where id = p_change_order_id for update;
  if v_co.id is null then
    raise exception 'Change order % not found', p_change_order_id using errcode = 'P0002';
  end if;
  if v_co.status <> 'presented' then
    raise exception 'Change order is % and cannot be decided', v_co.status
      using errcode = 'check_violation';
  end if;

  if p_approve then
    -- Who agreed, and how, is the whole value of the record. Without it there
    -- is nothing to point at when the final bill is questioned.
    if p_method = 'signature' and p_signature_id is null then
      raise exception 'A signature approval needs the signature'
        using errcode = 'check_violation';
    end if;
    if p_method <> 'signature'
       and (p_customer_name is null or length(trim(p_customer_name)) = 0) then
      raise exception 'Record who agreed on the customer side'
        using errcode = 'check_violation';
    end if;
  elsif p_reason is null or length(trim(p_reason)) = 0 then
    raise exception 'A reason is required when the customer declines'
      using errcode = 'check_violation';
  end if;

  update change_orders
  set status = case when p_approve then 'approved' else 'rejected' end::change_order_status,
      decided_at = now(),
      approval_method = case when p_approve then p_method else null end,
      customer_name = case when p_approve then p_customer_name else customer_name end,
      signature_id = case when p_approve then p_signature_id else null end,
      decision_reason = p_reason,
      recorded_by = auth_user_id()
  where id = p_change_order_id
  returning * into v_co;

  return v_co;
end;
$$;

-- ---------------------------------------------------------------------------
-- Costing against the contract price, not the original quote
-- ---------------------------------------------------------------------------

drop view if exists job_costs;

create view job_costs
with (security_invoker = true)
as
select
  j.id as job_id,
  j.org_id,
  j.job_number,
  j.title,
  j.status,
  j.customer_id,
  j.site_id,
  j.template_id,
  coalesce(j.quoted_price, 0)          as base_price,
  job_change_order_total(j.id)         as change_order_total,
  job_contract_price(j.id)             as contract_price,
  job_pending_change_order_total(j.id) as pending_change_orders,
  job_labour_cost(j.id)    as labour_cost,
  job_material_cost(j.id)  as material_cost,
  job_purchase_cost(j.id)  as purchase_cost,
  job_mileage_cost(j.id)   as mileage_cost,
  job_equipment_cost(j.id) as equipment_cost,
  job_rental_cost(j.id)    as rental_cost,
  (
    job_labour_cost(j.id) + job_material_cost(j.id) + job_purchase_cost(j.id)
    + job_mileage_cost(j.id) + job_equipment_cost(j.id) + job_rental_cost(j.id)
  ) as total_cost,
  (
    job_contract_price(j.id) - (
      job_labour_cost(j.id) + job_material_cost(j.id) + job_purchase_cost(j.id)
      + job_mileage_cost(j.id) + job_equipment_cost(j.id) + job_rental_cost(j.id)
    )
  ) as margin
from jobs j
where j.deleted_at is null
  -- Margin is owner, manager and bookkeeper information, not field information.
  and has_permission('costing.view');

comment on view job_costs is
  'Per-job cost rollup against the contract price (base quote plus approved '
  'change orders). All components derived.';

-- ---------------------------------------------------------------------------
-- Completion gate: no closing a job with money still on the table
-- ---------------------------------------------------------------------------

create or replace function job_completion_blockers(p_job_id uuid)
returns text[]
language plpgsql
stable
as $$
declare
  v_job jobs;
  v_req jsonb;
  v_blockers text[] := '{}';
  v_form jsonb;
  v_pending int;
begin
  select * into v_job from jobs where id = p_job_id;
  if v_job.id is null then
    return array['Job not found'];
  end if;

  select coalesce(t.completion_requirements, '{}'::jsonb) into v_req
  from job_templates t where t.id = v_job.template_id;
  v_req := coalesce(v_req, '{}'::jsonb);

  if coalesce((v_req ->> 'photos_before')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'before' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'Before photos required');
  end if;

  if coalesce((v_req ->> 'photos_after')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'after' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'After photos required');
  end if;

  if coalesce((v_req ->> 'customer_signature')::boolean, false)
     and not exists (
       select 1 from signatures where job_id = p_job_id and kind = 'completion'
     ) then
    v_blockers := array_append(v_blockers, 'Customer completion signature required');
  end if;

  for v_form in select * from jsonb_array_elements(coalesce(v_req -> 'forms', '[]'::jsonb)) loop
    if not exists (
      select 1
      from form_submissions s
      join form_templates ft on ft.id = s.template_id
      where s.job_id = p_job_id
        and ft.key = (v_form #>> '{}')
        and s.is_complete
    ) then
      v_blockers := array_append(v_blockers, 'Form not complete: ' || (v_form #>> '{}'));
    end if;
  end loop;

  if exists (
    select 1 from time_entries where job_id = p_job_id and clock_out_at is null
  ) then
    v_blockers := array_append(v_blockers,
      'Open time entries — everyone must be clocked out');
  end if;

  -- The gate that stops air scrubbers being forgotten at finished jobs.
  if exists (
    select 1
    from equipment_assignments a
    where a.job_id = p_job_id
      and a.kind = 'site_staging'
      and a.ended_at is null
      and a.expected_end_at is null
  ) then
    v_blockers := array_append(v_blockers,
      'Equipment still staged at site with no pickup scheduled');
  end if;

  if exists (
    select 1 from equipment_rentals
    where job_id = p_job_id
      and status in ('on_hire', 'overdue')
      and return_due_at is null
  ) then
    v_blockers := array_append(v_blockers,
      'Rented equipment outstanding with no return date');
  end if;

  -- Work billed flat and direct to the customer: a change order still waiting
  -- on an answer is money the job will never collect once the crew drives
  -- away. Settle it before the job closes.
  select count(*) into v_pending
  from change_orders where job_id = p_job_id and status in ('draft', 'presented');

  if v_pending > 0 then
    v_blockers := array_append(v_blockers,
      v_pending || ' change order(s) not yet agreed with the customer');
  end if;

  return v_blockers;
end;
$$;

-- ---------------------------------------------------------------------------
-- Permissions
-- ---------------------------------------------------------------------------

alter table change_orders enable row level security;
alter table change_orders force row level security;
alter table change_order_photos enable row level security;
alter table change_order_photos force row level security;

create policy change_orders_select on change_orders for select
  using (org_id = auth_org_id() and can_see_job(job_id));

-- The person who finds the extra damage drafts it; only a manager prices and
-- presents it.
create policy change_orders_draft on change_orders for insert
  with check (
    org_id = auth_org_id()
    and status = 'draft'
    and has_permission('changeorder.draft')
    and can_see_job(job_id)
  );

create policy change_orders_own_draft on change_orders for update
  using (created_by = auth_user_id() and status = 'draft')
  with check (created_by = auth_user_id());

create policy change_orders_manage on change_orders for all
  using (org_id = auth_org_id() and has_permission('changeorder.manage'))
  with check (org_id = auth_org_id() and has_permission('changeorder.manage'));

create policy change_order_photos_select on change_order_photos for select
  using (exists (
    select 1 from change_orders co
    where co.id = change_order_id and co.org_id = auth_org_id() and can_see_job(co.job_id)
  ));
create policy change_order_photos_write on change_order_photos for all
  using (exists (
    select 1 from change_orders co
    where co.id = change_order_id and co.org_id = auth_org_id()
      and (has_permission('changeorder.draft') or has_permission('changeorder.manage'))
  ))
  with check (exists (
    select 1 from change_orders co
    where co.id = change_order_id and co.org_id = auth_org_id()
  ));

-- Grant the new flags to existing roles, and to every org provisioned later.
update roles set permissions = permissions || '{"changeorder.draft": true, "changeorder.manage": true}'::jsonb
where key in ('owner', 'manager');

update roles set permissions = permissions || '{"changeorder.draft": true}'::jsonb
where key in ('crew_lead', 'technician');

