-- ===========================================================
-- 0018_price_visibility.sql
-- ===========================================================
-- 0018 Price visibility
--
-- What a job is worth is manager and owner information. The crew needs the
-- address, the scope, the equipment and the evidence to finish the work; they
-- do not need the number the customer is paying, and change order amounts are
-- pricing too.
--
-- Postgres RLS is row level, and under Supabase every signed-in user is the
-- same `authenticated` role, so a column grant cannot tell a manager from a
-- technician. The only enforcement that actually holds is: revoke the money
-- columns from `authenticated` on the base tables, and expose them through
-- definer-rights views that check the permission flag. Those views run as
-- their owner and therefore bypass RLS, so each one re-applies the row filter
-- its base table's policy would have applied.

-- ---------------------------------------------------------------------------
-- The flag
--
-- Deliberately separate from costing.view: seeing the price the customer pays
-- and seeing what the job cost us are different questions, and a role could
-- reasonably have one without the other.
-- ---------------------------------------------------------------------------

update roles
set permissions = permissions || '{"price.view": true}'::jsonb
where key in ('owner', 'manager', 'bookkeeper');

-- ---------------------------------------------------------------------------
-- Money-reading functions become definer, or they break for everyone once the
-- columns are revoked.
-- ---------------------------------------------------------------------------

create or replace function job_change_order_total(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(sum(amount), 0)
  from change_orders
  where job_id = p_job_id and status = 'approved';
$$;

create or replace function job_contract_price(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select quoted_price from jobs where id = p_job_id), 0)
       + job_change_order_total(p_job_id);
$$;

create or replace function job_pending_change_order_total(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(sum(amount), 0)
  from change_orders
  where job_id = p_job_id and status = 'presented';
$$;

create or replace function job_purchase_cost(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(sum(l.quantity * coalesce(l.estimated_unit_cost, 0)), 0)
  from purchase_request_lines l
  join purchase_requests r on r.id = l.request_id
  where r.job_id = p_job_id
    and l.line_status = 'approved'
    and r.status not in ('draft', 'rejected', 'cancelled');
$$;

create or replace function job_labour_cost(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(sum(time_entry_hours(t) * coalesce(p.cost_rate, 0)), 0)
  from time_entries t
  join profiles p on p.id = t.user_id
  where t.job_id = p_job_id and t.clock_out_at is not null;
$$;

-- ---------------------------------------------------------------------------
-- The safe read paths
-- ---------------------------------------------------------------------------

-- Everything a field user legitimately needs about a job, with the money
-- masked unless they hold price.view. This is what both clients read; the
-- base table keeps the column for writes and for the costing rollup.
create or replace view jobs_safe as
select
  j.id, j.org_id, j.job_number, j.customer_id, j.site_id, j.template_id,
  j.title, j.description, j.status, j.priority,
  j.scheduled_start, j.scheduled_end, j.actual_start, j.actual_end,
  case when has_permission('price.view') then j.quoted_price end as quoted_price,
  case when has_permission('price.view') then job_contract_price(j.id) end as contract_price,
  case when has_permission('price.view') then job_change_order_total(j.id) end as change_order_total,
  j.insurance_claim_no, j.adjuster_contact, j.recurrence_rule, j.parent_job_id,
  j.blocked_reason, j.cancelled_reason, j.created_by, j.created_at, j.updated_at
from jobs j
where j.deleted_at is null
  and j.org_id = auth_org_id()
  and can_see_job(j.id);

comment on view jobs_safe is
  'Jobs as a field user may read them: price masked unless price.view. Definer '
  'rights, so the row filter from the jobs RLS policy is repeated here.';

-- A crew lead drafts a change order describing what they found; the amount is
-- the manager''s to set and to see.
create or replace view change_orders_safe as
select
  co.id, co.org_id, co.job_id, co.seq, co.title, co.description,
  case when has_permission('price.view') then co.amount end as amount,
  co.added_hours, co.status, co.presented_at, co.decided_at,
  co.approval_method, co.customer_name, co.signature_id, co.decision_reason,
  co.created_by, co.presented_by, co.recorded_by, co.created_at, co.updated_at
from change_orders co
where co.org_id = auth_org_id()
  and can_see_job(co.job_id);

comment on view change_orders_safe is
  'Change orders with the amount masked unless price.view.';

-- profiles_safe was security_invoker, which left cost_rate readable straight
-- off the base table. Same treatment: definer rights, explicit row filter.
drop view if exists profiles_safe;

create view profiles_safe as
select
  p.id, p.org_id, p.role_id, p.full_name, p.email, p.phone,
  p.is_active, p.created_at,
  case when has_permission('user.view_cost_rates') then p.cost_rate end as cost_rate
from profiles p
where p.org_id = auth_org_id();

-- job_costs read quoted_price directly and was security_invoker, so the
-- revoke below would have broken it for everyone. Definer rights plus its own
-- org filter, keeping the costing.view gate exactly as it was.
drop view if exists job_costs;

create view job_costs as
select
  j.id as job_id,
  j.org_id,
  j.job_number,
  j.title,
  j.status,
  j.customer_id,
  j.site_id,
  j.template_id,
  coalesce(j.quoted_price, 0)          as base_price,
  job_change_order_total(j.id)         as change_order_total,
  job_contract_price(j.id)             as contract_price,
  job_pending_change_order_total(j.id) as pending_change_orders,
  job_labour_cost(j.id)    as labour_cost,
  job_material_cost(j.id)  as material_cost,
  job_purchase_cost(j.id)  as purchase_cost,
  job_mileage_cost(j.id)   as mileage_cost,
  job_equipment_cost(j.id) as equipment_cost,
  job_rental_cost(j.id)    as rental_cost,
  (
    job_labour_cost(j.id) + job_material_cost(j.id) + job_purchase_cost(j.id)
    + job_mileage_cost(j.id) + job_equipment_cost(j.id) + job_rental_cost(j.id)
  ) as total_cost,
  (
    job_contract_price(j.id) - (
      job_labour_cost(j.id) + job_material_cost(j.id) + job_purchase_cost(j.id)
      + job_mileage_cost(j.id) + job_equipment_cost(j.id) + job_rental_cost(j.id)
    )
  ) as margin
from jobs j
where j.deleted_at is null
  and j.org_id = auth_org_id()
  -- Margin is owner, manager and bookkeeper information, not field information.
  and has_permission('costing.view');

comment on view job_costs is
  'Per-job cost rollup against the contract price. Definer rights, gated on '
  'costing.view, org filter applied explicitly.';

-- ---------------------------------------------------------------------------
-- Close the direct path
--
-- Without this the views are decoration: a technician could read the column
-- straight off the table. Note the cost: `select *` on these tables now fails
-- for app users, which is why clients read jobs through jobs_safe.
-- ---------------------------------------------------------------------------

-- A column-level revoke cannot override an existing table-level SELECT grant:
-- Postgres keeps the broader grant and the revoke silently does nothing. The
-- only way to withhold one column is to drop the table grant and re-grant the
-- columns that remain. Doing it by enumeration would rot the first time
-- someone adds a column, so this derives the list.
create or replace function grant_columns_except(p_table text, p_exclude text[])
returns void
language plpgsql
as $$
declare
  v_cols text;
begin
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    return;
  end if;

  execute format('revoke select on %I from authenticated', p_table);

  select string_agg(quote_ident(column_name), ', ' order by ordinal_position)
  into v_cols
  from information_schema.columns
  where table_schema = 'public'
    and table_name = p_table
    and not (column_name = any(p_exclude));

  execute format('grant select (%s) on %I to authenticated', v_cols, p_table);
end;
$$;

comment on function grant_columns_except(text, text[]) is
  'Withholds columns from the authenticated role. Re-run for a table after '
  'adding a column to it, or the new column stays unreadable.';

select grant_columns_except('jobs', array['quoted_price']);
select grant_columns_except('change_orders', array['amount']);
select grant_columns_except('profiles', array['cost_rate']);

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant select on jobs_safe, change_orders_safe, profiles_safe, job_costs to authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on jobs, change_orders, profiles from anon';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Every org provisioned from here on
-- ---------------------------------------------------------------------------

create or replace function provision_org_roles(p_org_id uuid)
returns void
language plpgsql
as $$
begin
  insert into roles (org_id, key, name, is_system, permissions) values
  (p_org_id, 'owner', 'Owner', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.close', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'changeorder.draft', true, 'changeorder.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.approve_unlimited', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'user.view_cost_rates', true,
    'role.manage', true, 'org.manage_settings', true, 'audit.view', true,
    'price.view', true, 'costing.view', true, 'export.run', true
  )),

  (p_org_id, 'manager', 'Manager', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'changeorder.draft', true, 'changeorder.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'audit.view', true,
    'price.view', true, 'costing.view', true, 'export.run', true
  )),

  -- No price.view: a crew lead runs the work, not the commercials.
  (p_org_id, 'crew_lead', 'Crew Lead', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'changeorder.draft', true,
    'inventory.log_usage', true, 'inventory.transfer', true,
    'equipment.place', true,
    'time.log_others', true
  )),

  (p_org_id, 'technician', 'Technician', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'changeorder.draft', true,
    'inventory.log_usage', true,
    'equipment.place', true
  )),

  -- Keeps the books, so needs the price but never the margin conversation.
  (p_org_id, 'bookkeeper', 'Bookkeeper', true, jsonb_build_object(
    'job.view_all', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'mileage.view_all', true, 'time.view_all', true,
    'audit.view', true, 'price.view', true, 'costing.view', true, 'export.run', true,
    'job.close', true
  ))
  on conflict (org_id, key) do nothing;
end;
$$;

-- ===========================================================
-- 0019_simplified_job_flow.sql
-- ===========================================================
-- 0019 A shorter job flow, without closing the door on the longer one
--
-- The crew wants three steps: accept, on site and working, done. The full
-- lifecycle stays in the enum — en_route, on_site and blocked are all still
-- valid values, and any history already recorded against them stays readable.
-- What changes is which moves are offered, and that is now data.
--
-- To bring a step back later:
--
--   update job_transitions set enabled = true
--   where (from_status, to_status) in (('accepted','en_route'), ('en_route','on_site'));
--   update organizations set settings = jsonb_set(
--     settings, '{job_steps}',
--     '["accepted","en_route","on_site","in_progress","work_complete"]');
--
-- One UPDATE. No migration, no deploy, no app release.

alter table job_transitions
  add column enabled boolean not null default true;

comment on column job_transitions.enabled is
  'Whether this move is offered. Disabled moves stay in the table so the '
  'longer flow can be switched back on without a migration.';

-- Accept straight into work, skipping the en-route and arrival steps.
insert into job_transitions (from_status, to_status, required_permission, guard, enabled)
values ('accepted', 'in_progress', 'job.accept', null, true)
on conflict (from_status, to_status) do update set enabled = true;

-- The steps this crew does not use. Nothing is deleted.
update job_transitions
set enabled = false
where (from_status, to_status) in (
  ('accepted',    'en_route'),
  ('en_route',    'on_site'),
  ('en_route',    'cancelled'),
  ('on_site',     'in_progress'),
  ('on_site',     'blocked'),
  ('in_progress', 'blocked'),
  ('blocked',     'in_progress'),
  ('blocked',     'cancelled')
);

-- Which steps the crew's progress track shows, in order. Read by the clients;
-- the enabled column above is what actually enforces it.
update organizations
set settings = settings || jsonb_build_object(
  'job_steps', jsonb_build_array('accepted', 'in_progress', 'work_complete'),
  -- Two galleries: what it looked like before, and what it looked like after.
  -- 'during' stays a valid photo_phase, it is simply not offered.
  'photo_phases', jsonb_build_array('before', 'after')
);

-- ---------------------------------------------------------------------------
-- The transition function honours it
-- ---------------------------------------------------------------------------

create or replace function transition_job(
  p_job_id uuid,
  p_to_status job_status,
  p_note text default null
)
returns jobs
language plpgsql
security definer
set search_path = public
as $$
declare
  v_job jobs;
  v_rule job_transitions;
  v_blockers text[];
  v_pending int;
begin
  select * into v_job from jobs where id = p_job_id and deleted_at is null
  for update;

  if v_job.id is null then
    raise exception 'Job % not found', p_job_id using errcode = 'P0002';
  end if;

  if v_job.status = p_to_status then
    return v_job;
  end if;

  select * into v_rule from job_transitions
  where from_status = v_job.status and to_status = p_to_status;

  if v_rule.from_status is null then
    raise exception 'Illegal job transition % -> %', v_job.status, p_to_status
      using errcode = 'check_violation';
  end if;

  -- A move that exists but is switched off for this org.
  if not v_rule.enabled then
    raise exception 'Transition % -> % is not enabled for this organisation',
      v_job.status, p_to_status
      using errcode = 'check_violation';
  end if;

  if not has_permission(v_rule.required_permission) then
    raise exception 'Permission % required to move job % -> %',
      v_rule.required_permission, v_job.status, p_to_status
      using errcode = 'insufficient_privilege';
  end if;

  if v_rule.guard = 'reason' and (p_note is null or length(trim(p_note)) = 0) then
    raise exception 'A reason is required to move job % -> %', v_job.status, p_to_status
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'scheduled'
     and (v_job.scheduled_start is null or v_job.scheduled_end is null) then
    raise exception 'Job must have a scheduled window before it can be scheduled'
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'assigned'
     and not exists (select 1 from job_assignments where job_id = p_job_id) then
    raise exception 'Job must have at least one assignee'
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'all_accepted' then
    select count(*) into v_pending
    from job_assignments
    where job_id = p_job_id and acceptance_status <> 'accepted';
    if v_pending > 0 then
      raise exception '% assignee(s) have not accepted', v_pending
        using errcode = 'check_violation';
    end if;
  end if;

  if v_rule.guard = 'completion' then
    v_blockers := job_completion_blockers(p_job_id);
    if array_length(v_blockers, 1) > 0 then
      raise exception 'Job cannot be completed: %', array_to_string(v_blockers, '; ')
        using errcode = 'check_violation';
    end if;
  end if;

  update jobs
  set status = p_to_status,
      blocked_reason   = case when p_to_status = 'blocked' then p_note else null end,
      cancelled_reason = case when p_to_status = 'cancelled' then p_note else cancelled_reason end,
      -- Arrival is whichever of these the org's flow reaches first: with the
      -- short flow there is no separate on-site step, so starting work is
      -- when the crew got there.
      actual_start = case
        when p_to_status in ('on_site', 'in_progress') and actual_start is null then now()
        else actual_start end,
      actual_end = case
        when p_to_status = 'work_complete' then now()
        else actual_end end
  where id = p_job_id
  returning * into v_job;

  insert into job_status_history (org_id, job_id, from_status, to_status, changed_by, note)
  values (v_job.org_id, p_job_id, v_rule.from_status, p_to_status, auth_user_id(), p_note);

  return v_job;
end;
$$;

-- What the clients should offer from here, already filtered.
create or replace function job_next_steps(p_job_id uuid)
returns table (to_status job_status, required_permission text, guard text)
language sql
stable
as $$
  select t.to_status, t.required_permission, t.guard
  from job_transitions t
  join jobs j on j.id = p_job_id
  where t.from_status = j.status and t.enabled;
$$;

-- ===========================================================
-- 0020_completion_gate.sql
-- ===========================================================
-- 0020 A completion gate that directs rather than obstructs
--
-- The gate had four items on it at the end of a three-day job, and two of them
-- were not the crew's to resolve:
--
--   "1 person still clocked in" — clocking out is the last thing you do, and
--   so is marking the job complete, so the app demanded one before allowing
--   the other with no obvious order. Worse, a crew lead could not finish the
--   job until two colleagues each remembered to tap a button on their own
--   phones. A blocker that depends on other people's housekeeping is the kind
--   that gets an app uninstalled.
--
--   "Rental still out — set a return" — vendor returns are arranged by the
--   office, not by a crew standing in a driveway at 4pm.
--
-- Completing the job IS the signal that work stopped, so completion now
-- closes the clocks itself, stamped at the completion time — more accurate
-- than whenever each person remembered. What remains blocking is what only
-- the crew can supply and what cannot be reconstructed later: the after
-- photos and the customer's signature.

alter table time_entries
  add column auto_closed boolean not null default false;

comment on column time_entries.auto_closed is
  'Clocked out by job completion rather than by the person. Visible so a '
  'manager can spot and correct a shift that really did run longer.';

-- ---------------------------------------------------------------------------
-- Blocking: only what the crew alone can supply, and only what cannot be
-- reconstructed once they have driven away.
-- ---------------------------------------------------------------------------

create or replace function job_completion_blockers(p_job_id uuid)
returns text[]
language plpgsql
stable
as $$
declare
  v_job jobs;
  v_req jsonb;
  v_blockers text[] := '{}';
  v_form jsonb;
  v_pending int;
begin
  select * into v_job from jobs where id = p_job_id;
  if v_job.id is null then
    return array['Job not found'];
  end if;

  select coalesce(t.completion_requirements, '{}'::jsonb) into v_req
  from job_templates t where t.id = v_job.template_id;
  v_req := coalesce(v_req, '{}'::jsonb);

  if coalesce((v_req ->> 'photos_before')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'before' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'Before photos required');
  end if;

  if coalesce((v_req ->> 'photos_after')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'after' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'After photos required');
  end if;

  if coalesce((v_req ->> 'customer_signature')::boolean, false)
     and not exists (
       select 1 from signatures where job_id = p_job_id and kind = 'completion'
     ) then
    v_blockers := array_append(v_blockers, 'Customer sign-off required');
  end if;

  for v_form in select * from jsonb_array_elements(coalesce(v_req -> 'forms', '[]'::jsonb)) loop
    if not exists (
      select 1
      from form_submissions s
      join form_templates ft on ft.id = s.template_id
      where s.job_id = p_job_id
        and ft.key = (v_form #>> '{}')
        and s.is_complete
    ) then
      v_blockers := array_append(v_blockers, 'Form not complete: ' || (v_form #>> '{}'));
    end if;
  end loop;

  -- Equipment left at a site with no collection arranged stays blocking. It is
  -- the one thing on this list that becomes invisible the moment the crew
  -- leaves, and a forgotten scrubber costs more than the tap it takes to set
  -- a date. The completion screen offers "schedule pickup" inline.
  if exists (
    select 1
    from equipment_assignments a
    where a.job_id = p_job_id
      and a.kind = 'site_staging'
      and a.ended_at is null
      and a.expected_end_at is null
  ) then
    v_blockers := array_append(v_blockers,
      'Equipment still staged at site with no pickup scheduled');
  end if;

  -- Money the customer has not answered on yet. Once the crew drives away it
  -- is never collected, so this one is worth the friction.
  select count(*) into v_pending
  from change_orders where job_id = p_job_id and status in ('draft', 'presented');

  if v_pending > 0 then
    v_blockers := array_append(v_blockers,
      v_pending || ' change order(s) not yet agreed with the customer');
  end if;

  return v_blockers;
end;
$$;

-- ---------------------------------------------------------------------------
-- Warnings: true, worth saying, nobody's reason to stand in a driveway.
-- ---------------------------------------------------------------------------

create or replace function job_completion_warnings(p_job_id uuid)
returns text[]
language plpgsql
stable
as $$
declare
  v_warnings text[] := '{}';
  v_open int;
  v_rentals int;
begin
  select count(*) into v_open
  from time_entries where job_id = p_job_id and clock_out_at is null;

  if v_open > 0 then
    v_warnings := array_append(v_warnings,
      v_open || ' person(s) will be clocked out now');
  end if;

  -- Any rental still with us at completion, date set or not. "Job finished,
  -- vendor still has gear out" is the signal the office needs; whether a
  -- return date exists is a detail.
  select count(*) into v_rentals
  from equipment_rentals
  where job_id = p_job_id
    and status in ('on_hire', 'overdue');

  if v_rentals > 0 then
    v_warnings := array_append(v_warnings,
      v_rentals || ' rental(s) still out — the office will be told');
  end if;

  return v_warnings;
end;
$$;

comment on function job_completion_warnings(uuid) is
  'Things worth telling the crew at completion that are not theirs to fix. '
  'Shown as information; never refuses the transition.';

-- ---------------------------------------------------------------------------
-- Completing a job closes the clocks and flags the office
-- ---------------------------------------------------------------------------

create or replace function transition_job(
  p_job_id uuid,
  p_to_status job_status,
  p_note text default null
)
returns jobs
language plpgsql
security definer
set search_path = public
as $$
declare
  v_job jobs;
  v_rule job_transitions;
  v_blockers text[];
  v_pending int;
  v_manager uuid;
begin
  select * into v_job from jobs where id = p_job_id and deleted_at is null
  for update;

  if v_job.id is null then
    raise exception 'Job % not found', p_job_id using errcode = 'P0002';
  end if;

  if v_job.status = p_to_status then
    return v_job;
  end if;

  select * into v_rule from job_transitions
  where from_status = v_job.status and to_status = p_to_status;

  if v_rule.from_status is null then
    raise exception 'Illegal job transition % -> %', v_job.status, p_to_status
      using errcode = 'check_violation';
  end if;

  if not v_rule.enabled then
    raise exception 'Transition % -> % is not enabled for this organisation',
      v_job.status, p_to_status
      using errcode = 'check_violation';
  end if;

  if not has_permission(v_rule.required_permission) then
    raise exception 'Permission % required to move job % -> %',
      v_rule.required_permission, v_job.status, p_to_status
      using errcode = 'insufficient_privilege';
  end if;

  if v_rule.guard = 'reason' and (p_note is null or length(trim(p_note)) = 0) then
    raise exception 'A reason is required to move job % -> %', v_job.status, p_to_status
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'scheduled'
     and (v_job.scheduled_start is null or v_job.scheduled_end is null) then
    raise exception 'Job must have a scheduled window before it can be scheduled'
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'assigned'
     and not exists (select 1 from job_assignments where job_id = p_job_id) then
    raise exception 'Job must have at least one assignee'
      using errcode = 'check_violation';
  end if;

  if v_rule.guard = 'all_accepted' then
    select count(*) into v_pending
    from job_assignments
    where job_id = p_job_id and acceptance_status <> 'accepted';
    if v_pending > 0 then
      raise exception '% assignee(s) have not accepted', v_pending
        using errcode = 'check_violation';
    end if;
  end if;

  if v_rule.guard = 'completion' then
    v_blockers := job_completion_blockers(p_job_id);
    if array_length(v_blockers, 1) > 0 then
      raise exception 'Job cannot be completed: %', array_to_string(v_blockers, '; ')
        using errcode = 'check_violation';
    end if;
  end if;

  update jobs
  set status = p_to_status,
      blocked_reason   = case when p_to_status = 'blocked' then p_note else null end,
      cancelled_reason = case when p_to_status = 'cancelled' then p_note else cancelled_reason end,
      actual_start = case
        when p_to_status in ('on_site', 'in_progress') and actual_start is null then now()
        else actual_start end,
      actual_end = case
        when p_to_status = 'work_complete' then now()
        else actual_end end
  where id = p_job_id
  returning * into v_job;

  -- Finishing the job is the truthful clock-out moment. Marked auto_closed so
  -- a manager can see which stamps the app supplied and correct any that
  -- really did run longer.
  if p_to_status = 'work_complete' then
    update time_entries
    set clock_out_at = now(), auto_closed = true
    where job_id = p_job_id and clock_out_at is null;

    -- A rental still out is the office's to chase, so tell the office.
    for v_manager in
      select p.id from profiles p
      join roles r on r.id = p.role_id
      where p.org_id = v_job.org_id and p.is_active
        and coalesce((r.permissions ->> 'equipment.rental_manage')::boolean, false)
    loop
      insert into notifications (org_id, user_id, kind, title, body, payload)
      select v_job.org_id, v_manager, 'rental_outstanding',
             'Rental still out on a finished job',
             v_job.job_number || ' is complete with ' || count(*) || ' rental(s) not returned',
             jsonb_build_object('job_id', p_job_id)
      from equipment_rentals
      where job_id = p_job_id and status in ('on_hire', 'overdue')
      having count(*) > 0;
    end loop;
  end if;

  insert into job_status_history (org_id, job_id, from_status, to_status, changed_by, note)
  values (v_job.org_id, p_job_id, v_rule.from_status, p_to_status, auth_user_id(), p_note);

  return v_job;
end;
$$;

